window.GAOKAO_PAPERS=window.GAOKAO_PAPERS||{};window.GAOKAO_PAPERS["2022-new_gaokao_paper_1"]=[{"id":"2022-new_gaokao_paper_1-q01","paperId":"2022-new_gaokao_paper_1","number":1,"type":"single","score":5,"lessonIds":["1.3","3.1"],"difficulty":"基础","hint":"先把 √x<4 化为 0≤x<16，别漏掉根号要求 x≥0，再与 3x≥1 取公共部分。","legacy":false,"legacyReason":"","searchText":"若集合 M=\\{x\\mid \\sqrt{x}<4\\} ， N=\\{x\\mid 3x\\ge 1\\} ，则 M\\cap N= （ ） \\{x\\mid 0\\le x<2\\} \\left\\{x\\mid \\frac13\\le x<2\\right\\} \\{x\\mid 3\\le x<16\\} \\left\\{x\\mid \\frac13\\le x<16\\right\\}","questionHtml":"若集合 <span class=\"gk-math\" data-tex=\"M=\\{x\\mid \\sqrt{x}&lt;4\\}\">M=\\{x\\mid \\sqrt{x}&lt;4\\}</span>，<span class=\"gk-math\" data-tex=\"N=\\{x\\mid 3x\\ge 1\\}\">N=\\{x\\mid 3x\\ge 1\\}</span>，则 <span class=\"gk-math\" data-tex=\"M\\cap N=\">M\\cap N=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\{x\\mid 0\\le x&lt;2\\}\">\\{x\\mid 0\\le x&lt;2\\}</span>","<span class=\"gk-math\" data-tex=\"\\left\\{x\\mid \\frac13\\le x&lt;2\\right\\}\">\\left\\{x\\mid \\frac13\\le x&lt;2\\right\\}</span>","<span class=\"gk-math\" data-tex=\"\\{x\\mid 3\\le x&lt;16\\}\">\\{x\\mid 3\\le x&lt;16\\}</span>","<span class=\"gk-math\" data-tex=\"\\left\\{x\\mid \\frac13\\le x&lt;16\\right\\}\">\\left\\{x\\mid \\frac13\\le x&lt;16\\right\\}</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"\\sqrt{x}\">\\sqrt{x}</span> 有意义要求 <span class=\"gk-math\" data-tex=\"x\\ge 0\">x\\ge 0</span>，而 <span class=\"gk-math\" data-tex=\"\\sqrt{x}&lt;4\">\\sqrt{x}&lt;4</span> 两边均为非负数，平方得 <span class=\"gk-math\" data-tex=\"x&lt;16\">x&lt;16</span>，所以 <span class=\"gk-math\" data-tex=\"M=\\left\\{x\\mid 0\\le x&lt;16\\right\\}\">M=\\left\\{x\\mid 0\\le x&lt;16\\right\\}</span>. 由 <span class=\"gk-math\" data-tex=\"3x\\ge 1\">3x\\ge 1</span> 得 <span class=\"gk-math\" data-tex=\"x\\ge \\frac13\">x\\ge \\frac13</span>，所以 <span class=\"gk-math\" data-tex=\"N=\\left\\{x\\mid x\\ge \\frac13\\right\\}\">N=\\left\\{x\\mid x\\ge \\frac13\\right\\}</span>. 因此 <span class=\"gk-math\" data-tex=\"M\\cap N=\\left\\{x\\mid \\frac13\\le x&lt;16\\right\\}\">M\\cap N=\\left\\{x\\mid \\frac13\\le x&lt;16\\right\\}</span>. 故选 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q02","paperId":"2022-new_gaokao_paper_1","number":2,"type":"single","score":5,"lessonIds":["7.2","7.1"],"difficulty":"基础","hint":"先由 i(1−z)=1 解出 z，再写出它的共轭复数，相加时虚部会抵消。","legacy":false,"legacyReason":"","searchText":"若 \\i(1-z)=1 ，则 z+\\overline{z}= （ ） -2 -1 1 2","questionHtml":"若 <span class=\"gk-math\" data-tex=\"\\i(1-z)=1\">\\i(1-z)=1</span>，则 <span class=\"gk-math\" data-tex=\"z+\\overline{z}=\">z+\\overline{z}=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"-2\">-2</span>","<span class=\"gk-math\" data-tex=\"-1\">-1</span>","1","2"],"answerHtml":"D","answerKey":"D","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"\\i\\left(1-z\\right)=1\">\\i\\left(1-z\\right)=1</span>，所以 <span class=\"gk-math\" data-tex=\"1-z=\\frac{1}{\\i}=-\\i\">1-z=\\frac{1}{\\i}=-\\i</span>，这里用到了 <span class=\"gk-math\" data-tex=\"\\i\\cdot \\left(-\\i\\right)=1\">\\i\\cdot \\left(-\\i\\right)=1</span>. 于是 <span class=\"gk-math\" data-tex=\"z=1+\\i\">z=1+\\i</span>，<span class=\"gk-math\" data-tex=\"\\overline{z}=1-\\i\">\\overline{z}=1-\\i</span>. 相加得 <span class=\"gk-math\" data-tex=\"z+\\overline{z}=2\">z+\\overline{z}=2</span>. 故选 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q03","paperId":"2022-new_gaokao_paper_1","number":3,"type":"single","score":5,"lessonIds":["6.2","6.3"],"difficulty":"基础","hint":"BD=2DA 表示 D 在 A 到 B 的三分之一处，先把 CD 写成 CA+AD。","legacy":false,"legacyReason":"","searchText":"在 \\triangle ABC 中，点 D 在边 AB 上， BD=2DA . 记 \\overrightarrow{CA}=\\bs m ， \\overrightarrow{CD}=\\bs n ，则 \\overrightarrow{CB}= （ ） 3\\bs m-2\\bs n -2\\bs m+3\\bs n 3\\bs m+2\\bs n 2\\bs m+3\\bs n","questionHtml":"在 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 中，点 <span class=\"gk-math\" data-tex=\"D\">D</span> 在边 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 上，<span class=\"gk-math\" data-tex=\"BD=2DA\">BD=2DA</span>. 记 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CA}=\\bs m\">\\overrightarrow{CA}=\\bs m</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{CD}=\\bs n\">\\overrightarrow{CD}=\\bs n</span>，则 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CB}=\">\\overrightarrow{CB}=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"3\\bs m-2\\bs n\">3\\bs m-2\\bs n</span>","<span class=\"gk-math\" data-tex=\"-2\\bs m+3\\bs n\">-2\\bs m+3\\bs n</span>","<span class=\"gk-math\" data-tex=\"3\\bs m+2\\bs n\">3\\bs m+2\\bs n</span>","<span class=\"gk-math\" data-tex=\"2\\bs m+3\\bs n\">2\\bs m+3\\bs n</span>"],"answerHtml":"B","answerKey":"B","solutionHtml":"<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,166px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q3_solution_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q3_solution_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"150\" height=\"133\" style=\"aspect-ratio:150/133;width:100%\" loading=\"lazy\"></button></figure><br><br>因为点 <span class=\"gk-math\" data-tex=\"D\">D</span> 在边 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 上且 <span class=\"gk-math\" data-tex=\"BD=2DA\">BD=2DA</span>，所以 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AD}=\\frac13\\overrightarrow{AB}\">\\overrightarrow{AD}=\\frac13\\overrightarrow{AB}</span>. 于是 <span class=\"gk-math\" data-tex=\"\\bs n=\\overrightarrow{CD}=\\overrightarrow{CA}+\\overrightarrow{AD}=\\bs m+\\frac13\\overrightarrow{AB}\">\\bs n=\\overrightarrow{CD}=\\overrightarrow{CA}+\\overrightarrow{AD}=\\bs m+\\frac13\\overrightarrow{AB}</span>. 又 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AB}=\\overrightarrow{CB}-\\overrightarrow{CA}=\\overrightarrow{CB}-\\bs m\">\\overrightarrow{AB}=\\overrightarrow{CB}-\\overrightarrow{CA}=\\overrightarrow{CB}-\\bs m</span>，代入得 <span class=\"gk-math\" data-tex=\"\\bs n=\\bs m+\\frac13\\left(\\overrightarrow{CB}-\\bs m\\right)=\\frac23\\bs m+\\frac13\\overrightarrow{CB}\">\\bs n=\\bs m+\\frac13\\left(\\overrightarrow{CB}-\\bs m\\right)=\\frac23\\bs m+\\frac13\\overrightarrow{CB}</span>. 两边乘以 <span class=\"gk-math\" data-tex=\"3\">3</span> 并移项得 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CB}=3\\bs n-2\\bs m=-2\\bs m+3\\bs n\">\\overrightarrow{CB}=3\\bs n-2\\bs m=-2\\bs m+3\\bs n</span>. 故选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q04","paperId":"2022-new_gaokao_paper_1","number":4,"type":"single","score":5,"lessonIds":["8.3"],"difficulty":"基础","hint":"增加的水量是棱台体积，高为 157.5−148.5=9 米；面积从平方千米换成平方米后再代公式。","legacy":false,"legacyReason":"","searchText":"南水北调工程缓解了北方一些地区水资源短缺问题，其中一部分水蓄入某水库. 已知该水库水位为海拔 148.5\\text{m} 时，相应水面的面积为 140.0\\text{km}^2 ；水位为海拔 157.5\\text{m} 时，相应水面的面积为 180.0\\text{km}^2 . 将该水库在这两个水位间的形状看作一个棱台，则该水库水位从海拔 148.5\\text{m} 上升到 157.5\\text{m} 时，增加的水量约为（ \\sqrt7\\approx 2.65 ）（ ） 1.0\\times 10^9\\text{m}^3 1.2\\times 10^9\\text{m}^3 1.4\\times 10^9\\text{m}^3 1.6\\times 10^9\\text{m}^3","questionHtml":"南水北调工程缓解了北方一些地区水资源短缺问题，其中一部分水蓄入某水库. 已知该水库水位为海拔 <span class=\"gk-math\" data-tex=\"148.5\\text{m}\">148.5\\text{m}</span> 时，相应水面的面积为 <span class=\"gk-math\" data-tex=\"140.0\\text{km}^2\">140.0\\text{km}^2</span>；水位为海拔 <span class=\"gk-math\" data-tex=\"157.5\\text{m}\">157.5\\text{m}</span> 时，相应水面的面积为 <span class=\"gk-math\" data-tex=\"180.0\\text{km}^2\">180.0\\text{km}^2</span>. 将该水库在这两个水位间的形状看作一个棱台，则该水库水位从海拔 <span class=\"gk-math\" data-tex=\"148.5\\text{m}\">148.5\\text{m}</span> 上升到 <span class=\"gk-math\" data-tex=\"157.5\\text{m}\">157.5\\text{m}</span> 时，增加的水量约为（<span class=\"gk-math\" data-tex=\"\\sqrt7\\approx 2.65\">\\sqrt7\\approx 2.65</span>）（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"1.0\\times 10^9\\text{m}^3\">1.0\\times 10^9\\text{m}^3</span>","<span class=\"gk-math\" data-tex=\"1.2\\times 10^9\\text{m}^3\">1.2\\times 10^9\\text{m}^3</span>","<span class=\"gk-math\" data-tex=\"1.4\\times 10^9\\text{m}^3\">1.4\\times 10^9\\text{m}^3</span>","<span class=\"gk-math\" data-tex=\"1.6\\times 10^9\\text{m}^3\">1.6\\times 10^9\\text{m}^3</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"因为水位从海拔 <span class=\"gk-math\" data-tex=\"148.5\\text{ m}\">148.5\\text{ m}</span> 上升到 <span class=\"gk-math\" data-tex=\"157.5\\text{ m}\">157.5\\text{ m}</span>，所以棱台的高为 <span class=\"gk-math\" data-tex=\"h=157.5-148.5=9\\text{ m}\">h=157.5-148.5=9\\text{ m}</span>. 记下底面积为 <span class=\"gk-math\" data-tex=\"S=140.0\\text{ km}^2=140\\times 10^6\\text{ m}^2\">S=140.0\\text{ km}^2=140\\times 10^6\\text{ m}^2</span>，上底面积为 <span class=\"gk-math\" data-tex=\"S^{\\prime}=180.0\\text{ km}^2=180\\times 10^6\\text{ m}^2\">S^{\\prime}=180.0\\text{ km}^2=180\\times 10^6\\text{ m}^2</span>，这里用到了 <span class=\"gk-math\" data-tex=\"1\\text{ km}^2=10^6\\text{ m}^2\">1\\text{ km}^2=10^6\\text{ m}^2</span>. 由棱台体积公式 <span class=\"gk-math\" data-tex=\"V=\\frac13h\\left(S+S^{\\prime}+\\sqrt{SS^{\\prime}}\\right)\">V=\\frac13h\\left(S+S^{\\prime}+\\sqrt{SS^{\\prime}}\\right)</span>，而 <span class=\"gk-math\" data-tex=\"\\sqrt{SS^{\\prime}}=\\sqrt{140\\times 180}\\times 10^6\\text{ m}^2=60\\sqrt{7}\\times 10^6\\text{ m}^2\\approx 60\\times 2.65\\times 10^6\\text{ m}^2=159\\times 10^6\\text{ m}^2\">\\sqrt{SS^{\\prime}}=\\sqrt{140\\times 180}\\times 10^6\\text{ m}^2=60\\sqrt{7}\\times 10^6\\text{ m}^2\\approx 60\\times 2.65\\times 10^6\\text{ m}^2=159\\times 10^6\\text{ m}^2</span>. 所以 <span class=\"gk-math\" data-tex=\"V\\approx \\frac13\\times 9\\times \\left(140+180+159\\right)\\times 10^6\\text{ m}^3=1437\\times 10^6\\text{ m}^3=1.437\\times 10^9\\text{ m}^3\">V\\approx \\frac13\\times 9\\times \\left(140+180+159\\right)\\times 10^6\\text{ m}^3=1437\\times 10^6\\text{ m}^3=1.437\\times 10^9\\text{ m}^3</span>. 故增加的水量约为 <span class=\"gk-math\" data-tex=\"1.4\\times 10^9\\text{ m}^3\">1.4\\times 10^9\\text{ m}^3</span>，选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q05","paperId":"2022-new_gaokao_paper_1","number":5,"type":"single","score":5,"lessonIds":["10.1","e3-6.2"],"difficulty":"基础","hint":"总共有七选二种无序数对，逐个检查互质数对，注意互质不要求两个数都是质数。","legacy":false,"legacyReason":"","searchText":"从 2 至 8 的 7 个整数中随机取 2 个不同的数，则这 2 个数互质的概率为（ ） \\dfrac16 \\dfrac13 \\dfrac12 \\dfrac23","questionHtml":"从 <span class=\"gk-math\" data-tex=\"2\">2</span> 至 <span class=\"gk-math\" data-tex=\"8\">8</span> 的 <span class=\"gk-math\" data-tex=\"7\">7</span> 个整数中随机取 <span class=\"gk-math\" data-tex=\"2\">2</span> 个不同的数，则这 <span class=\"gk-math\" data-tex=\"2\">2</span> 个数互质的概率为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\dfrac16\">\\dfrac16</span>","<span class=\"gk-math\" data-tex=\"\\dfrac13\">\\dfrac13</span>","<span class=\"gk-math\" data-tex=\"\\dfrac12\">\\dfrac12</span>","<span class=\"gk-math\" data-tex=\"\\dfrac23\">\\dfrac23</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"从 <span class=\"gk-math\" data-tex=\"2\">2</span> 至 <span class=\"gk-math\" data-tex=\"8\">8</span> 的 <span class=\"gk-math\" data-tex=\"7\">7</span> 个整数中任取 <span class=\"gk-math\" data-tex=\"2\">2</span> 个不同数的取法共有 <span class=\"gk-math\" data-tex=\"\\mathrm C_7^2=21\">\\mathrm C_7^2=21</span> 种. 若两数不互质，则它们有大于 <span class=\"gk-math\" data-tex=\"1\">1</span> 的公约数. 在 <span class=\"gk-math\" data-tex=\"2\">2</span>，<span class=\"gk-math\" data-tex=\"3\">3</span>，<span class=\"gk-math\" data-tex=\"4\">4</span>，<span class=\"gk-math\" data-tex=\"5\">5</span>，<span class=\"gk-math\" data-tex=\"6\">6</span>，<span class=\"gk-math\" data-tex=\"7\">7</span>，<span class=\"gk-math\" data-tex=\"8\">8</span> 中，偶数为 <span class=\"gk-math\" data-tex=\"2\">2</span>，<span class=\"gk-math\" data-tex=\"4\">4</span>，<span class=\"gk-math\" data-tex=\"6\">6</span>，<span class=\"gk-math\" data-tex=\"8\">8</span>，其中任取 <span class=\"gk-math\" data-tex=\"2\">2</span> 个均不互质，共有 <span class=\"gk-math\" data-tex=\"\\mathrm C_4^2=6\">\\mathrm C_4^2=6</span> 种，即 <span class=\"gk-math\" data-tex=\"\\left(2,4\\right)\">\\left(2,4\\right)</span>，<span class=\"gk-math\" data-tex=\"\\left(2,6\\right)\">\\left(2,6\\right)</span>，<span class=\"gk-math\" data-tex=\"\\left(2,8\\right)\">\\left(2,8\\right)</span>，<span class=\"gk-math\" data-tex=\"\\left(4,6\\right)\">\\left(4,6\\right)</span>，<span class=\"gk-math\" data-tex=\"\\left(4,8\\right)\">\\left(4,8\\right)</span>，<span class=\"gk-math\" data-tex=\"\\left(6,8\\right)\">\\left(6,8\\right)</span>. 既非全偶又不互质的只能是 <span class=\"gk-math\" data-tex=\"3\">3</span> 与 <span class=\"gk-math\" data-tex=\"6\">6</span> 的组合，即 <span class=\"gk-math\" data-tex=\"\\left(3,6\\right)\">\\left(3,6\\right)</span>. 其余含 <span class=\"gk-math\" data-tex=\"5\">5</span>，<span class=\"gk-math\" data-tex=\"7\">7</span> 或 <span class=\"gk-math\" data-tex=\"3\">3</span> 与非 <span class=\"gk-math\" data-tex=\"6\">6</span> 偶数的组合均互质. 所以不互质的取法共 <span class=\"gk-math\" data-tex=\"6+1=7\">6+1=7</span> 种，互质的取法共 <span class=\"gk-math\" data-tex=\"21-7=14\">21-7=14</span> 种. 因此所求概率为 <span class=\"gk-math\" data-tex=\"\\frac{14}{21}=\\frac23\">\\frac{14}{21}=\\frac23</span>. 故选 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q06","paperId":"2022-new_gaokao_paper_1","number":6,"type":"single","score":5,"lessonIds":["5.4","5.6"],"difficulty":"进阶","hint":"由周期范围先缩小 ω 的范围，再由对称中心纵坐标求 b，横坐标确定相位。","legacy":false,"legacyReason":"","searchText":"记函数 f(x)=\\sin\\left(\\omega x+\\frac{\\pi}{4}\\right)+b （ \\omega>0 ） 的最小正周期为 T . 若 \\frac{2\\pi}{3}<T<\\pi ，且 y=f(x) 的图象关于点 \\left(\\frac{3\\pi}{2},2\\right) 中心对称，则 f\\left(\\frac{\\pi}{2}\\right)= （ ） 1 \\dfrac32 \\dfrac52 3","questionHtml":"记函数 <span class=\"gk-math\" data-tex=\"f(x)=\\sin\\left(\\omega x+\\frac{\\pi}{4}\\right)+b\">f(x)=\\sin\\left(\\omega x+\\frac{\\pi}{4}\\right)+b</span>（<span class=\"gk-math\" data-tex=\"\\omega&gt;0\">\\omega&gt;0</span>） 的最小正周期为 <span class=\"gk-math\" data-tex=\"T\">T</span>. 若 <span class=\"gk-math\" data-tex=\"\\frac{2\\pi}{3}&lt;T&lt;\\pi\">\\frac{2\\pi}{3}&lt;T&lt;\\pi</span>，且 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 的图象关于点 <span class=\"gk-math\" data-tex=\"\\left(\\frac{3\\pi}{2},2\\right)\">\\left(\\frac{3\\pi}{2},2\\right)</span> 中心对称，则 <span class=\"gk-math\" data-tex=\"f\\left(\\frac{\\pi}{2}\\right)=\">f\\left(\\frac{\\pi}{2}\\right)=</span>（ ）","optionsHtml":["1","<span class=\"gk-math\" data-tex=\"\\dfrac32\">\\dfrac32</span>","<span class=\"gk-math\" data-tex=\"\\dfrac52\">\\dfrac52</span>","3"],"answerHtml":"A","answerKey":"A","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"f\\left(x\\right)=\\sin\\left(\\omega x+\\frac{\\pi}{4}\\right)+b\">f\\left(x\\right)=\\sin\\left(\\omega x+\\frac{\\pi}{4}\\right)+b</span> 的最小正周期为 <span class=\"gk-math\" data-tex=\"T=\\frac{2\\pi}{\\omega}\">T=\\frac{2\\pi}{\\omega}</span>，由 <span class=\"gk-math\" data-tex=\"\\frac{2\\pi}{3}&lt;T&lt;\\pi\">\\frac{2\\pi}{3}&lt;T&lt;\\pi</span> 得 <span class=\"gk-math\" data-tex=\"2&lt;\\omega&lt;3\">2&lt;\\omega&lt;3</span>. 若 <span class=\"gk-math\" data-tex=\"y=f\\left(x\\right)\">y=f\\left(x\\right)</span> 的图象关于点 <span class=\"gk-math\" data-tex=\"\\left(\\frac{3\\pi}{2},2\\right)\">\\left(\\frac{3\\pi}{2},2\\right)</span> 中心对称，则正弦部分的中心纵坐标为 <span class=\"gk-math\" data-tex=\"0\">0</span>，所以 <span class=\"gk-math\" data-tex=\"b=2\">b=2</span>，且 <span class=\"gk-math\" data-tex=\"\\sin\\left(\\frac{3\\pi}{2}\\omega+\\frac{\\pi}{4}\\right)=0\">\\sin\\left(\\frac{3\\pi}{2}\\omega+\\frac{\\pi}{4}\\right)=0</span>. 于是存在 <span class=\"gk-math\" data-tex=\"k\\in\\Z\">k\\in\\Z</span>，使得 <span class=\"gk-math\" data-tex=\"\\frac{3\\pi}{2}\\omega+\\frac{\\pi}{4}=k\\pi\">\\frac{3\\pi}{2}\\omega+\\frac{\\pi}{4}=k\\pi</span>. 两边除以 <span class=\"gk-math\" data-tex=\"\\pi\">\\pi</span> 得 <span class=\"gk-math\" data-tex=\"\\frac32\\omega+\\frac14=k\">\\frac32\\omega+\\frac14=k</span>，即 <span class=\"gk-math\" data-tex=\"\\omega=\\frac{4k-1}{6}\">\\omega=\\frac{4k-1}{6}</span>. 结合 <span class=\"gk-math\" data-tex=\"2&lt;\\omega&lt;3\">2&lt;\\omega&lt;3</span> 得 <span class=\"gk-math\" data-tex=\"2&lt;\\frac{4k-1}{6}&lt;3\">2&lt;\\frac{4k-1}{6}&lt;3</span>，即 <span class=\"gk-math\" data-tex=\"\\frac{13}{4}&lt;k&lt;\\frac{19}{4}\">\\frac{13}{4}&lt;k&lt;\\frac{19}{4}</span>. 因为 <span class=\"gk-math\" data-tex=\"k\\in\\Z\">k\\in\\Z</span>，所以 <span class=\"gk-math\" data-tex=\"k=4\">k=4</span>，从而 <span class=\"gk-math\" data-tex=\"\\omega=\\frac{15}{6}=\\frac52\">\\omega=\\frac{15}{6}=\\frac52</span>. 因此 <span class=\"gk-math\" data-tex=\"f\\left(x\\right)=\\sin\\left(\\frac52x+\\frac{\\pi}{4}\\right)+2\">f\\left(x\\right)=\\sin\\left(\\frac52x+\\frac{\\pi}{4}\\right)+2</span>，所以 <span class=\"gk-math\" data-tex=\"f\\left(\\frac{\\pi}{2}\\right)=\\sin\\left(\\frac{5\\pi}{4}+\\frac{\\pi}{4}\\right)+2=\\sin\\left(\\frac{3\\pi}{2}\\right)+2=-1+2=1\">f\\left(\\frac{\\pi}{2}\\right)=\\sin\\left(\\frac{5\\pi}{4}+\\frac{\\pi}{4}\\right)+2=\\sin\\left(\\frac{3\\pi}{2}\\right)+2=-1+2=1</span>. 故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q07","paperId":"2022-new_gaokao_paper_1","number":7,"type":"single","score":5,"lessonIds":["e2-5.3","4.4","4.2"],"difficulty":"挑战","hint":"把三个数都看作 x=0.1 时的函数值，先比较 e^x 与 1/(1−x)，再比较 −ln(1−x)。","legacy":false,"legacyReason":"","searchText":"设 a=0.1\\e^{0.1} ， b=\\frac{0.1}{1-0.1} ， c=-\\ln 0.9 ，则（ ） a<b<c c<b<a c<a<b a<c<b","questionHtml":"设 <span class=\"gk-math\" data-tex=\"a=0.1\\e^{0.1}\">a=0.1\\e^{0.1}</span>，<span class=\"gk-math\" data-tex=\"b=\\frac{0.1}{1-0.1}\">b=\\frac{0.1}{1-0.1}</span>，<span class=\"gk-math\" data-tex=\"c=-\\ln 0.9\">c=-\\ln 0.9</span>，则（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"a&lt;b&lt;c\">a&lt;b&lt;c</span>","<span class=\"gk-math\" data-tex=\"c&lt;b&lt;a\">c&lt;b&lt;a</span>","<span class=\"gk-math\" data-tex=\"c&lt;a&lt;b\">c&lt;a&lt;b</span>","<span class=\"gk-math\" data-tex=\"a&lt;c&lt;b\">a&lt;c&lt;b</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"记 <span class=\"gk-math\" data-tex=\"x=0.1\">x=0.1</span>，则 <span class=\"gk-math\" data-tex=\"a=x\\e^{x}\">a=x\\e^{x}</span>，<span class=\"gk-math\" data-tex=\"b=\\frac{x}{1-x}=\\frac19\">b=\\frac{x}{1-x}=\\frac19</span>，<span class=\"gk-math\" data-tex=\"c=-\\ln\\left(1-x\\right)\">c=-\\ln\\left(1-x\\right)</span>. 先证 <span class=\"gk-math\" data-tex=\"a&lt;b\">a&lt;b</span>. 设 <span class=\"gk-math\" data-tex=\"h\\left(x\\right)=\\left(1-x\\right)\\e^{x}\">h\\left(x\\right)=\\left(1-x\\right)\\e^{x}</span>，<span class=\"gk-math\" data-tex=\"x\\in\\left[0,0.1\\right]\">x\\in\\left[0,0.1\\right]</span>，则 <span class=\"gk-math\" data-tex=\"h^{\\prime}\\left(x\\right)=-\\e^{x}+\\left(1-x\\right)\\e^{x}=-x\\e^{x}\\le 0\">h^{\\prime}\\left(x\\right)=-\\e^{x}+\\left(1-x\\right)\\e^{x}=-x\\e^{x}\\le 0</span>，且仅在 <span class=\"gk-math\" data-tex=\"x=0\">x=0</span> 处取零，所以 <span class=\"gk-math\" data-tex=\"h\\left(x\\right)\">h\\left(x\\right)</span> 在 <span class=\"gk-math\" data-tex=\"\\left[0,0.1\\right]\">\\left[0,0.1\\right]</span> 上单调递减. 因为 <span class=\"gk-math\" data-tex=\"h\\left(0\\right)=1\">h\\left(0\\right)=1</span>，所以 <span class=\"gk-math\" data-tex=\"h\\left(0.1\\right)&lt;1\">h\\left(0.1\\right)&lt;1</span>，即 <span class=\"gk-math\" data-tex=\"0.9\\e^{0.1}&lt;1\">0.9\\e^{0.1}&lt;1</span>，也就是 <span class=\"gk-math\" data-tex=\"\\e^{0.1}&lt;\\frac{10}{9}\">\\e^{0.1}&lt;\\frac{10}{9}</span>. 两边乘以 <span class=\"gk-math\" data-tex=\"0.1\">0.1</span> 得 <span class=\"gk-math\" data-tex=\"0.1\\e^{0.1}&lt;\\frac19\">0.1\\e^{0.1}&lt;\\frac19</span>，即 <span class=\"gk-math\" data-tex=\"a&lt;b\">a&lt;b</span>. 再证 <span class=\"gk-math\" data-tex=\"c&lt;a\">c&lt;a</span>. 设 <span class=\"gk-math\" data-tex=\"k\\left(x\\right)=x\\e^{x}+\\ln\\left(1-x\\right)\">k\\left(x\\right)=x\\e^{x}+\\ln\\left(1-x\\right)</span>，<span class=\"gk-math\" data-tex=\"x\\in\\left[0,0.1\\right]\">x\\in\\left[0,0.1\\right]</span>，则 <span class=\"gk-math\" data-tex=\"k\\left(0\\right)=0\">k\\left(0\\right)=0</span>，且 <span class=\"gk-math\" data-tex=\"k^{\\prime}\\left(x\\right)=\\e^{x}+x\\e^{x}-\\frac{1}{1-x}=\\left(1+x\\right)\\e^{x}-\\frac{1}{1-x}\">k^{\\prime}\\left(x\\right)=\\e^{x}+x\\e^{x}-\\frac{1}{1-x}=\\left(1+x\\right)\\e^{x}-\\frac{1}{1-x}</span>，<span class=\"gk-math\" data-tex=\"k^{\\prime}\\left(0\\right)=0\">k^{\\prime}\\left(0\\right)=0</span>. 又 <span class=\"gk-math\" data-tex=\"k^{\\prime\\prime}\\left(x\\right)=\\left(2+x\\right)\\e^{x}-\\frac{1}{\\left(1-x\\right)^2}\">k^{\\prime\\prime}\\left(x\\right)=\\left(2+x\\right)\\e^{x}-\\frac{1}{\\left(1-x\\right)^2}</span>. 为证 <span class=\"gk-math\" data-tex=\"k^{\\prime\\prime}\\left(x\\right)&gt;0\">k^{\\prime\\prime}\\left(x\\right)&gt;0</span>，先证 <span class=\"gk-math\" data-tex=\"\\e^{x}\\ge 1+x\">\\e^{x}\\ge 1+x</span>. 设 <span class=\"gk-math\" data-tex=\"s\\left(x\\right)=\\e^{x}-x-1\">s\\left(x\\right)=\\e^{x}-x-1</span>，则 <span class=\"gk-math\" data-tex=\"s^{\\prime}\\left(x\\right)=\\e^{x}-1\\ge 0\">s^{\\prime}\\left(x\\right)=\\e^{x}-1\\ge 0</span>，<span class=\"gk-math\" data-tex=\"x\\ge 0\">x\\ge 0</span>，所以 <span class=\"gk-math\" data-tex=\"s\\left(x\\right)\">s\\left(x\\right)</span> 单调递增，又 <span class=\"gk-math\" data-tex=\"s\\left(0\\right)=0\">s\\left(0\\right)=0</span>，故 <span class=\"gk-math\" data-tex=\"x\\ge 0\">x\\ge 0</span> 时 <span class=\"gk-math\" data-tex=\"\\e^{x}\\ge 1+x\">\\e^{x}\\ge 1+x</span>. 于是 <span class=\"gk-math\" data-tex=\"\\left(2+x\\right)\\e^{x}\\ge \\left(2+x\\right)\\left(1+x\\right)\">\\left(2+x\\right)\\e^{x}\\ge \\left(2+x\\right)\\left(1+x\\right)</span>. 而 <span class=\"gk-math\" data-tex=\"\\left(2+x\\right)\\left(1+x\\right)-\\frac{1}{\\left(1-x\\right)^2}=\\frac{1-x-3x^2+x^3+x^4}{\\left(1-x\\right)^2}\">\\left(2+x\\right)\\left(1+x\\right)-\\frac{1}{\\left(1-x\\right)^2}=\\frac{1-x-3x^2+x^3+x^4}{\\left(1-x\\right)^2}</span>，分子 <span class=\"gk-math\" data-tex=\"=1-x-3x^2+x^3+x^4\\ge 1-0.1-0.03=0.87&gt;0\">=1-x-3x^2+x^3+x^4\\ge 1-0.1-0.03=0.87&gt;0</span>，<span class=\"gk-math\" data-tex=\"x\\in\\left[0,0.1\\right]\">x\\in\\left[0,0.1\\right]</span>，所以 <span class=\"gk-math\" data-tex=\"k^{\\prime\\prime}\\left(x\\right)&gt;0\">k^{\\prime\\prime}\\left(x\\right)&gt;0</span>，<span class=\"gk-math\" data-tex=\"x\\in\\left[0,0.1\\right]\">x\\in\\left[0,0.1\\right]</span>. 因此 <span class=\"gk-math\" data-tex=\"k^{\\prime}\\left(x\\right)\">k^{\\prime}\\left(x\\right)</span> 单调递增，又 <span class=\"gk-math\" data-tex=\"k^{\\prime}\\left(0\\right)=0\">k^{\\prime}\\left(0\\right)=0</span>，故 <span class=\"gk-math\" data-tex=\"x\\in\\left(0,0.1\\right]\">x\\in\\left(0,0.1\\right]</span> 时 <span class=\"gk-math\" data-tex=\"k^{\\prime}\\left(x\\right)&gt;0\">k^{\\prime}\\left(x\\right)&gt;0</span>. 从而 <span class=\"gk-math\" data-tex=\"k\\left(x\\right)\">k\\left(x\\right)</span> 单调递增，又 <span class=\"gk-math\" data-tex=\"k\\left(0\\right)=0\">k\\left(0\\right)=0</span>，故 <span class=\"gk-math\" data-tex=\"k\\left(0.1\\right)&gt;0\">k\\left(0.1\\right)&gt;0</span>，即 <span class=\"gk-math\" data-tex=\"0.1\\e^{0.1}+\\ln 0.9&gt;0\">0.1\\e^{0.1}+\\ln 0.9&gt;0</span>，也就是 <span class=\"gk-math\" data-tex=\"-\\ln 0.9&lt;0.1\\e^{0.1}\">-\\ln 0.9&lt;0.1\\e^{0.1}</span>，即 <span class=\"gk-math\" data-tex=\"c&lt;a\">c&lt;a</span>. 结合 <span class=\"gk-math\" data-tex=\"a&lt;b\">a&lt;b</span> 得 <span class=\"gk-math\" data-tex=\"c&lt;a&lt;b\">c&lt;a&lt;b</span>. 故选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q08","paperId":"2022-new_gaokao_paper_1","number":8,"type":"single","score":5,"lessonIds":["8.3","e2-5.3"],"difficulty":"挑战","hint":"先由球体积求半径，再设棱锥高 h，用截面圆和侧棱长把体积写成 h 的函数。","legacy":false,"legacyReason":"","searchText":"已知正四棱锥的侧棱长为 l ，其各顶点都在同一球面上. 若该球的体积为 36\\pi ，且 3\\le l\\le 3\\sqrt3 ，则该正四棱锥体积的取值范围是（ ） \\left[18,\\frac{81}{4}\\right] \\left[\\frac{27}{4},\\frac{81}{4}\\right] \\left[\\frac{27}{4},\\frac{64}{3}\\right] [18,27]","questionHtml":"已知正四棱锥的侧棱长为 <span class=\"gk-math\" data-tex=\"l\">l</span>，其各顶点都在同一球面上. 若该球的体积为 <span class=\"gk-math\" data-tex=\"36\\pi\">36\\pi</span>，且 <span class=\"gk-math\" data-tex=\"3\\le l\\le 3\\sqrt3\">3\\le l\\le 3\\sqrt3</span>，则该正四棱锥体积的取值范围是（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\left[18,\\frac{81}{4}\\right]\">\\left[18,\\frac{81}{4}\\right]</span>","<span class=\"gk-math\" data-tex=\"\\left[\\frac{27}{4},\\frac{81}{4}\\right]\">\\left[\\frac{27}{4},\\frac{81}{4}\\right]</span>","<span class=\"gk-math\" data-tex=\"\\left[\\frac{27}{4},\\frac{64}{3}\\right]\">\\left[\\frac{27}{4},\\frac{64}{3}\\right]</span>","<span class=\"gk-math\" data-tex=\"[18,27]\">[18,27]</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,419px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q8_solution_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q8_solution_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"403\" height=\"396\" style=\"aspect-ratio:403/396;width:100%\" loading=\"lazy\"></button></figure><br><br>因为球体积 <span class=\"gk-math\" data-tex=\"\\frac43\\pi R^3=36\\pi\">\\frac43\\pi R^3=36\\pi</span>，所以 <span class=\"gk-math\" data-tex=\"R^3=27\">R^3=27</span>，故 <span class=\"gk-math\" data-tex=\"R=3\">R=3</span>. 设正四棱锥底面正方形边长为 <span class=\"gk-math\" data-tex=\"2a\">2a</span>，<span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，高为 <span class=\"gk-math\" data-tex=\"h\">h</span>，<span class=\"gk-math\" data-tex=\"h&gt;0\">h&gt;0</span>，侧棱长为 <span class=\"gk-math\" data-tex=\"l\">l</span>，则底面对角线长的一半为 <span class=\"gk-math\" data-tex=\"\\sqrt{2}a\">\\sqrt{2}a</span>，故 <span class=\"gk-math\" data-tex=\"l^2=2a^2+h^2\">l^2=2a^2+h^2</span>. 又各顶点共球，球心在高线上，所以 <span class=\"gk-math\" data-tex=\"R^2=2a^2+\\left(h-R\\right)^2\">R^2=2a^2+\\left(h-R\\right)^2</span>，即 <span class=\"gk-math\" data-tex=\"2a^2=2Rh-h^2\">2a^2=2Rh-h^2</span>. 代入 <span class=\"gk-math\" data-tex=\"R=3\">R=3</span> 得 <span class=\"gk-math\" data-tex=\"2a^2=6h-h^2\">2a^2=6h-h^2</span>. 与 <span class=\"gk-math\" data-tex=\"l^2=2a^2+h^2\">l^2=2a^2+h^2</span> 联立消去 <span class=\"gk-math\" data-tex=\"a\">a</span> 得 <span class=\"gk-math\" data-tex=\"l^2=6h\">l^2=6h</span>，即 <span class=\"gk-math\" data-tex=\"h=\\frac{l^2}{6}\">h=\\frac{l^2}{6}</span>. 体积为 <span class=\"gk-math\" data-tex=\"V=\\frac13\\cdot \\left(2a\\right)^2h=\\frac43a^2h=\\frac23h\\left(l^2-h^2\\right)\">V=\\frac13\\cdot \\left(2a\\right)^2h=\\frac43a^2h=\\frac23h\\left(l^2-h^2\\right)</span>. 代入 <span class=\"gk-math\" data-tex=\"h=\\frac{l^2}{6}\">h=\\frac{l^2}{6}</span> 得 <span class=\"gk-math\" data-tex=\"V\\left(l\\right)=\\frac{l^4}{9}-\\frac{l^6}{324}\">V\\left(l\\right)=\\frac{l^4}{9}-\\frac{l^6}{324}</span>，<span class=\"gk-math\" data-tex=\"3\\le l\\le 3\\sqrt{3}\">3\\le l\\le 3\\sqrt{3}</span>. 求导得 <span class=\"gk-math\" data-tex=\"V^{\\prime}\\left(l\\right)=\\frac{4l^3}{9}-\\frac{l^5}{54}=\\frac{l^3\\left(24-l^2\\right)}{54}\">V^{\\prime}\\left(l\\right)=\\frac{4l^3}{9}-\\frac{l^5}{54}=\\frac{l^3\\left(24-l^2\\right)}{54}</span>. 令 <span class=\"gk-math\" data-tex=\"V^{\\prime}\\left(l\\right)=0\">V^{\\prime}\\left(l\\right)=0</span> 得 <span class=\"gk-math\" data-tex=\"l=2\\sqrt{6}\">l=2\\sqrt{6}</span>，且 <span class=\"gk-math\" data-tex=\"3&lt;2\\sqrt{6}&lt;3\\sqrt{3}\">3&lt;2\\sqrt{6}&lt;3\\sqrt{3}</span>. 当 <span class=\"gk-math\" data-tex=\"3\\le l&lt;2\\sqrt{6}\">3\\le l&lt;2\\sqrt{6}</span> 时 <span class=\"gk-math\" data-tex=\"V^{\\prime}\\left(l\\right)&gt;0\">V^{\\prime}\\left(l\\right)&gt;0</span>，当 <span class=\"gk-math\" data-tex=\"2\\sqrt{6}&lt;l\\le 3\\sqrt{3}\">2\\sqrt{6}&lt;l\\le 3\\sqrt{3}</span> 时 <span class=\"gk-math\" data-tex=\"V^{\\prime}\\left(l\\right)&lt;0\">V^{\\prime}\\left(l\\right)&lt;0</span>，所以 <span class=\"gk-math\" data-tex=\"V\\left(l\\right)\">V\\left(l\\right)</span> 先增后减，最大值在 <span class=\"gk-math\" data-tex=\"l=2\\sqrt{6}\">l=2\\sqrt{6}</span> 处取得，为 <span class=\"gk-math\" data-tex=\"V\\left(2\\sqrt{6}\\right)=\\frac{576}{9}-\\frac{13824}{324}=64-\\frac{128}{3}=\\frac{64}{3}\">V\\left(2\\sqrt{6}\\right)=\\frac{576}{9}-\\frac{13824}{324}=64-\\frac{128}{3}=\\frac{64}{3}</span>. 端点值为 <span class=\"gk-math\" data-tex=\"V\\left(3\\right)=9-\\frac{729}{324}=\\frac{27}{4}\">V\\left(3\\right)=9-\\frac{729}{324}=\\frac{27}{4}</span>，<span class=\"gk-math\" data-tex=\"V\\left(3\\sqrt{3}\\right)=81-\\frac{19683}{324}=\\frac{81}{4}\">V\\left(3\\sqrt{3}\\right)=81-\\frac{19683}{324}=\\frac{81}{4}</span>. 因为 <span class=\"gk-math\" data-tex=\"\\frac{27}{4}&lt;\\frac{81}{4}\">\\frac{27}{4}&lt;\\frac{81}{4}</span>，所以最小值为 <span class=\"gk-math\" data-tex=\"\\frac{27}{4}\">\\frac{27}{4}</span>. 故体积取值范围是 <span class=\"gk-math\" data-tex=\"\\left[\\frac{27}{4},\\frac{64}{3}\\right]\">\\left[\\frac{27}{4},\\frac{64}{3}\\right]</span>，选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q09","paperId":"2022-new_gaokao_paper_1","number":9,"type":"multiple","score":5,"lessonIds":["e1-1.4","8.6"],"difficulty":"进阶","hint":"给正方体三个相邻棱建立坐标，用方向向量的数量积和法向量逐项验证。","legacy":false,"legacyReason":"","searchText":"已知正方体 ABCD-A_1B_1C_1D_1 ，则（ ） 直线 BC_1 与 DA_1 所成的角为 90^\\circ 直线 BC_1 与 CA_1 所成的角为 90^\\circ 直线 BC_1 与平面 BB_1D_1D 所成的角为 45^\\circ 直线 BC_1 与平面 ABCD 所成的角为 45^\\circ","questionHtml":"已知正方体 <span class=\"gk-math\" data-tex=\"ABCD-A_1B_1C_1D_1\">ABCD-A_1B_1C_1D_1</span>，则（ ）","optionsHtml":["直线 <span class=\"gk-math\" data-tex=\"BC_1\">BC_1</span> 与 <span class=\"gk-math\" data-tex=\"DA_1\">DA_1</span> 所成的角为 <span class=\"gk-math\" data-tex=\"90^\\circ\">90^\\circ</span>","直线 <span class=\"gk-math\" data-tex=\"BC_1\">BC_1</span> 与 <span class=\"gk-math\" data-tex=\"CA_1\">CA_1</span> 所成的角为 <span class=\"gk-math\" data-tex=\"90^\\circ\">90^\\circ</span>","直线 <span class=\"gk-math\" data-tex=\"BC_1\">BC_1</span> 与平面 <span class=\"gk-math\" data-tex=\"BB_1D_1D\">BB_1D_1D</span> 所成的角为 <span class=\"gk-math\" data-tex=\"45^\\circ\">45^\\circ</span>","直线 <span class=\"gk-math\" data-tex=\"BC_1\">BC_1</span> 与平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 所成的角为 <span class=\"gk-math\" data-tex=\"45^\\circ\">45^\\circ</span>"],"answerHtml":"ABD","answerKey":"ABD","solutionHtml":"<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,302px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q9_solution_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q9_solution_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"286\" height=\"246\" style=\"aspect-ratio:286/246;width:100%\" loading=\"lazy\"></button></figure><br><br>设正方体棱长为 <span class=\"gk-math\" data-tex=\"1\">1</span>，取 <span class=\"gk-math\" data-tex=\"A(0,0,0)\">A(0,0,0)</span>，<span class=\"gk-math\" data-tex=\"B(1,0,0)\">B(1,0,0)</span>，<span class=\"gk-math\" data-tex=\"C(1,1,0)\">C(1,1,0)</span>，<span class=\"gk-math\" data-tex=\"D(0,1,0)\">D(0,1,0)</span>，<span class=\"gk-math\" data-tex=\"A_1(0,0,1)\">A_1(0,0,1)</span>，<span class=\"gk-math\" data-tex=\"B_1(1,0,1)\">B_1(1,0,1)</span>，<span class=\"gk-math\" data-tex=\"C_1(1,1,1)\">C_1(1,1,1)</span>. 因为 <span class=\"gk-math\" data-tex=\"\\overrightarrow{BC_1}=(0,1,1)\">\\overrightarrow{BC_1}=(0,1,1)</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{DA_1}=(0,-1,1)\">\\overrightarrow{DA_1}=(0,-1,1)</span>，内积为 <span class=\"gk-math\" data-tex=\"0\">0</span>，所以两直线垂直，故A正确. 因为 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CA_1}=(-1,-1,1)\">\\overrightarrow{CA_1}=(-1,-1,1)</span> 与 <span class=\"gk-math\" data-tex=\"\\overrightarrow{BC_1}\">\\overrightarrow{BC_1}</span> 的内积为 <span class=\"gk-math\" data-tex=\"0\">0</span>，所以 <span class=\"gk-math\" data-tex=\"BC_1\\perp CA_1\">BC_1\\perp CA_1</span>，故B正确. 因为 <span class=\"gk-math\" data-tex=\"BB_1\\perp A_1C_1\">BB_1\\perp A_1C_1</span> 且 <span class=\"gk-math\" data-tex=\"B_1D_1\\perp A_1C_1\">B_1D_1\\perp A_1C_1</span>，所以 <span class=\"gk-math\" data-tex=\"A_1C_1\\perp\">A_1C_1\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"BB_1D_1D\">BB_1D_1D</span>. 设 <span class=\"gk-math\" data-tex=\"O_1\">O_1</span> 为 <span class=\"gk-math\" data-tex=\"A_1C_1\">A_1C_1</span> 与 <span class=\"gk-math\" data-tex=\"B_1D_1\">B_1D_1</span> 的交点，则 <span class=\"gk-math\" data-tex=\"C_1O_1\\perp\">C_1O_1\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"BB_1D_1D\">BB_1D_1D</span>，而 <span class=\"gk-math\" data-tex=\"B\">B</span> 在该平面内，所以 <span class=\"gk-math\" data-tex=\"BO_1\">BO_1</span> 为 <span class=\"gk-math\" data-tex=\"BC_1\">BC_1</span> 在该平面上的射影，所成角为 <span class=\"gk-math\" data-tex=\"\\angle C_1BO_1\">\\angle C_1BO_1</span>. 因为 <span class=\"gk-math\" data-tex=\"\\lvert C_1O_1\\rvert=\\frac{\\sqrt{2}}{2}\">\\lvert C_1O_1\\rvert=\\frac{\\sqrt{2}}{2}</span>，<span class=\"gk-math\" data-tex=\"\\lvert BC_1\\rvert=\\sqrt{2}\">\\lvert BC_1\\rvert=\\sqrt{2}</span>，所以 <span class=\"gk-math\" data-tex=\"\\sin\\angle C_1BO_1=\\frac{1}{2}\">\\sin\\angle C_1BO_1=\\frac{1}{2}</span>，夹角为 <span class=\"gk-math\" data-tex=\"30^\\circ\">30^\\circ</span>，故C错误. 因为 <span class=\"gk-math\" data-tex=\"C_1C\\perp\">C_1C\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，所以 <span class=\"gk-math\" data-tex=\"BC_1\">BC_1</span> 与底面所成角为 <span class=\"gk-math\" data-tex=\"\\angle C_1BC=45^\\circ\">\\angle C_1BC=45^\\circ</span>，故D正确. 综上选ABD.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q10","paperId":"2022-new_gaokao_paper_1","number":10,"type":"multiple","score":5,"lessonIds":["e2-5.3","3.2"],"difficulty":"进阶","hint":"先求 f′(x)=3x²−1，再检查极值处函数值；中心对称可计算 f(x)+f(−x)。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x)=x^3-x+1 ，则（ ） f(x) 有两个极值点 f(x) 有三个零点 点 (0,1) 是曲线 y=f(x) 的对称中心 直线 y=2x 是曲线 y=f(x) 的切线","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)=x^3-x+1\">f(x)=x^3-x+1</span>，则（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 有两个极值点","<span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 有三个零点","点 <span class=\"gk-math\" data-tex=\"(0,1)\">(0,1)</span> 是曲线 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 的对称中心","直线 <span class=\"gk-math\" data-tex=\"y=2x\">y=2x</span> 是曲线 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 的切线"],"answerHtml":"AC","answerKey":"AC","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"f&#x27;(x)=3x^2-1\">f&#x27;(x)=3x^2-1</span>，令 <span class=\"gk-math\" data-tex=\"f&#x27;(x)=0\">f&#x27;(x)=0</span> 得 <span class=\"gk-math\" data-tex=\"x=\\pm\\frac{\\sqrt{3}}{3}\">x=\\pm\\frac{\\sqrt{3}}{3}</span>，且 <span class=\"gk-math\" data-tex=\"f&#x27;\">f&#x27;</span> 在这两点两侧变号，所以 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 有两个极值点，故A正确. 因为当 <span class=\"gk-math\" data-tex=\"x&lt;-\\frac{\\sqrt{3}}{3}\">x&lt;-\\frac{\\sqrt{3}}{3}</span> 或 <span class=\"gk-math\" data-tex=\"x&gt;\\frac{\\sqrt{3}}{3}\">x&gt;\\frac{\\sqrt{3}}{3}</span> 时 <span class=\"gk-math\" data-tex=\"f&#x27;(x)&gt;0\">f&#x27;(x)&gt;0</span>，当 <span class=\"gk-math\" data-tex=\"-\\frac{\\sqrt{3}}{3}&lt;x&lt;\\frac{\\sqrt{3}}{3}\">-\\frac{\\sqrt{3}}{3}&lt;x&lt;\\frac{\\sqrt{3}}{3}</span> 时 <span class=\"gk-math\" data-tex=\"f&#x27;(x)&lt;0\">f&#x27;(x)&lt;0</span>，所以 <span class=\"gk-math\" data-tex=\"x=-\\frac{\\sqrt{3}}{3}\">x=-\\frac{\\sqrt{3}}{3}</span> 为极大值点，<span class=\"gk-math\" data-tex=\"x=\\frac{\\sqrt{3}}{3}\">x=\\frac{\\sqrt{3}}{3}</span> 为极小值点. 又 <span class=\"gk-math\" data-tex=\"f\\left(-\\frac{\\sqrt{3}}{3}\\right)=1+\\frac{2\\sqrt{3}}{9}&gt;0\">f\\left(-\\frac{\\sqrt{3}}{3}\\right)=1+\\frac{2\\sqrt{3}}{9}&gt;0</span>，<span class=\"gk-math\" data-tex=\"f\\left(\\frac{\\sqrt{3}}{3}\\right)=1-\\frac{2\\sqrt{3}}{9}&gt;0\">f\\left(\\frac{\\sqrt{3}}{3}\\right)=1-\\frac{2\\sqrt{3}}{9}&gt;0</span>，且当 <span class=\"gk-math\" data-tex=\"x\\to -\\infty\">x\\to -\\infty</span> 时 <span class=\"gk-math\" data-tex=\"f(x)\\to -\\infty\">f(x)\\to -\\infty</span>，当 <span class=\"gk-math\" data-tex=\"x\\to +\\infty\">x\\to +\\infty</span> 时 <span class=\"gk-math\" data-tex=\"f(x)\\to +\\infty\">f(x)\\to +\\infty</span>，所以 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 仅在 <span class=\"gk-math\" data-tex=\"\\left(-\\infty,-\\frac{\\sqrt{3}}{3}\\right)\">\\left(-\\infty,-\\frac{\\sqrt{3}}{3}\\right)</span> 内有一个零点，故B错误. 因为 <span class=\"gk-math\" data-tex=\"h(x)=x^3-x\">h(x)=x^3-x</span> 满足 <span class=\"gk-math\" data-tex=\"h(-x)=-h(x)\">h(-x)=-h(x)</span>，为奇函数，图象关于原点对称，而 <span class=\"gk-math\" data-tex=\"f(x)=h(x)+1\">f(x)=h(x)+1</span> 为其向上平移 <span class=\"gk-math\" data-tex=\"1\">1</span> 个单位，所以 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 关于 <span class=\"gk-math\" data-tex=\"(0,1)\">(0,1)</span> 中心对称，故C正确. 因为令 <span class=\"gk-math\" data-tex=\"f&#x27;(x)=2\">f&#x27;(x)=2</span> 得 <span class=\"gk-math\" data-tex=\"x=\\pm 1\">x=\\pm 1</span>，<span class=\"gk-math\" data-tex=\"f(1)=1\">f(1)=1</span> 处切线为 <span class=\"gk-math\" data-tex=\"y=2x-1\">y=2x-1</span>，<span class=\"gk-math\" data-tex=\"f(-1)=1\">f(-1)=1</span> 处切线为 <span class=\"gk-math\" data-tex=\"y=2x+3\">y=2x+3</span>，斜率为 <span class=\"gk-math\" data-tex=\"2\">2</span> 的切点仅此两处，均不给出 <span class=\"gk-math\" data-tex=\"y=2x\">y=2x</span>，所以 <span class=\"gk-math\" data-tex=\"y=2x\">y=2x</span> 不是切线，故D错误. 综上选AC.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q11","paperId":"2022-new_gaokao_paper_1","number":11,"type":"multiple","score":5,"lessonIds":["e1-3.3","e1-2.2"],"difficulty":"挑战","hint":"先把 A=(1,1) 代入求 p，再设过 B 的直线联立抛物线，利用两根的和与积。","legacy":false,"legacyReason":"","searchText":"已知 O 为坐标原点，点 A(1,1) 在抛物线 C:\\ x^2=2py （ p>0 ） 上，过点 B(0,-1) 的直线交 C 于 P ， Q 两点，则（ ） C 的准线为 y=-1 直线 AB 与 C 相切 |OP|\\cdot |OQ|>|OA|^2 |BP|\\cdot |BQ|>|BA|^2","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"O\">O</span> 为坐标原点，点 <span class=\"gk-math\" data-tex=\"A(1,1)\">A(1,1)</span> 在抛物线 <span class=\"gk-math\" data-tex=\"C:\\ x^2=2py\">C:\\ x^2=2py</span>（<span class=\"gk-math\" data-tex=\"p&gt;0\">p&gt;0</span>） 上，过点 <span class=\"gk-math\" data-tex=\"B(0,-1)\">B(0,-1)</span> 的直线交 <span class=\"gk-math\" data-tex=\"C\">C</span> 于 <span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span> 两点，则（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"C\">C</span> 的准线为 <span class=\"gk-math\" data-tex=\"y=-1\">y=-1</span>","直线 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 与 <span class=\"gk-math\" data-tex=\"C\">C</span> 相切","<span class=\"gk-math\" data-tex=\"|OP|\\cdot |OQ|&gt;|OA|^2\">|OP|\\cdot |OQ|&gt;|OA|^2</span>","<span class=\"gk-math\" data-tex=\"|BP|\\cdot |BQ|&gt;|BA|^2\">|BP|\\cdot |BQ|&gt;|BA|^2</span>"],"answerHtml":"BCD","answerKey":"BCD","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"A(1,1)\">A(1,1)</span> 在 <span class=\"gk-math\" data-tex=\"x^2=2py\">x^2=2py</span> 上得 <span class=\"gk-math\" data-tex=\"1=2p\">1=2p</span>，即 <span class=\"gk-math\" data-tex=\"p=\\frac{1}{2}\">p=\\frac{1}{2}</span>，故抛物线为 <span class=\"gk-math\" data-tex=\"x^2=y\">x^2=y</span>，准线为 <span class=\"gk-math\" data-tex=\"y=-\\frac{1}{4}\">y=-\\frac{1}{4}</span>，所以A错误. 因为 <span class=\"gk-math\" data-tex=\"k_{AB}=\\frac{1-(-1)}{1-0}=2\">k_{AB}=\\frac{1-(-1)}{1-0}=2</span>，直线 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 为 <span class=\"gk-math\" data-tex=\"y=2x-1\">y=2x-1</span>，联立 <span class=\"gk-math\" data-tex=\"y=x^2\">y=x^2</span> 得 <span class=\"gk-math\" data-tex=\"x^2-2x+1=0\">x^2-2x+1=0</span>，即 <span class=\"gk-math\" data-tex=\"(x-1)^2=0\">(x-1)^2=0</span>，有重根 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span>，所以 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 与 <span class=\"gk-math\" data-tex=\"C\">C</span> 相切，故B正确. 设过 <span class=\"gk-math\" data-tex=\"B(0,-1)\">B(0,-1)</span> 交 <span class=\"gk-math\" data-tex=\"C\">C</span> 于 <span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span> 两点的直线为 <span class=\"gk-math\" data-tex=\"l\">l</span>，记 <span class=\"gk-math\" data-tex=\"P(x_1,y_1)\">P(x_1,y_1)</span>，<span class=\"gk-math\" data-tex=\"Q(x_2,y_2)\">Q(x_2,y_2)</span>. 若 <span class=\"gk-math\" data-tex=\"l\">l</span> 斜率不存在，则 <span class=\"gk-math\" data-tex=\"l\">l</span> 为 <span class=\"gk-math\" data-tex=\"x=0\">x=0</span> 或 <span class=\"gk-math\" data-tex=\"x=t\\ne 0\">x=t\\ne 0</span>，每条竖直线与 <span class=\"gk-math\" data-tex=\"y=x^2\">y=x^2</span> 至多交于一点，不构成两点 <span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span>，所以交于两点的 <span class=\"gk-math\" data-tex=\"l\">l</span> 必有斜率，设为 <span class=\"gk-math\" data-tex=\"y=kx-1\">y=kx-1</span>. 联立 <span class=\"gk-math\" data-tex=\"x^2=kx-1\">x^2=kx-1</span> 得 <span class=\"gk-math\" data-tex=\"x^2-kx+1=0\">x^2-kx+1=0</span>，有两个不同交点的充要条件是 <span class=\"gk-math\" data-tex=\"\\Delta=k^2-4&gt;0\">\\Delta=k^2-4&gt;0</span>，即 <span class=\"gk-math\" data-tex=\"\\lvert k\\rvert&gt;2\">\\lvert k\\rvert&gt;2</span>，此时根与系数关系为 <span class=\"gk-math\" data-tex=\"x_1+x_2=k\">x_1+x_2=k</span>，<span class=\"gk-math\" data-tex=\"x_1x_2=1\">x_1x_2=1</span>，且 <span class=\"gk-math\" data-tex=\"y_1=x_1^2\">y_1=x_1^2</span>，<span class=\"gk-math\" data-tex=\"y_2=x_2^2\">y_2=x_2^2</span>. 因为 <span class=\"gk-math\" data-tex=\"\\lvert OP\\rvert=\\sqrt{x_1^2+y_1^2}=\\lvert x_1\\rvert\\sqrt{1+x_1^2}\">\\lvert OP\\rvert=\\sqrt{x_1^2+y_1^2}=\\lvert x_1\\rvert\\sqrt{1+x_1^2}</span>，<span class=\"gk-math\" data-tex=\"\\lvert OQ\\rvert=\\lvert x_2\\rvert\\sqrt{1+x_2^2}\">\\lvert OQ\\rvert=\\lvert x_2\\rvert\\sqrt{1+x_2^2}</span>，所以 <span class=\"gk-math\" data-tex=\"\\lvert OP\\rvert\\cdot\\lvert OQ\\rvert=\\lvert x_1x_2\\rvert\\sqrt{(1+x_1^2)(1+x_2^2)}=\\sqrt{1+x_1^2+x_2^2+x_1^2x_2^2}\">\\lvert OP\\rvert\\cdot\\lvert OQ\\rvert=\\lvert x_1x_2\\rvert\\sqrt{(1+x_1^2)(1+x_2^2)}=\\sqrt{1+x_1^2+x_2^2+x_1^2x_2^2}</span>. 又 <span class=\"gk-math\" data-tex=\"x_1^2+x_2^2=(x_1+x_2)^2-2x_1x_2=k^2-2\">x_1^2+x_2^2=(x_1+x_2)^2-2x_1x_2=k^2-2</span>，<span class=\"gk-math\" data-tex=\"x_1^2x_2^2=1\">x_1^2x_2^2=1</span>，所以上式等于 <span class=\"gk-math\" data-tex=\"\\sqrt{2+k^2-2}=\\lvert k\\rvert\">\\sqrt{2+k^2-2}=\\lvert k\\rvert</span>. 因为 <span class=\"gk-math\" data-tex=\"\\lvert k\\rvert&gt;2\">\\lvert k\\rvert&gt;2</span>，所以 <span class=\"gk-math\" data-tex=\"\\lvert OP\\rvert\\cdot\\lvert OQ\\rvert=\\lvert k\\rvert&gt;2\">\\lvert OP\\rvert\\cdot\\lvert OQ\\rvert=\\lvert k\\rvert&gt;2</span>. 又 <span class=\"gk-math\" data-tex=\"\\lvert OA\\rvert^2=1^2+1^2=2\">\\lvert OA\\rvert^2=1^2+1^2=2</span>，所以 <span class=\"gk-math\" data-tex=\"\\lvert OP\\rvert\\cdot\\lvert OQ\\rvert&gt;\\lvert OA\\rvert^2\">\\lvert OP\\rvert\\cdot\\lvert OQ\\rvert&gt;\\lvert OA\\rvert^2</span>，故C正确. 因为 <span class=\"gk-math\" data-tex=\"y_1+1=kx_1\">y_1+1=kx_1</span>，<span class=\"gk-math\" data-tex=\"y_2+1=kx_2\">y_2+1=kx_2</span>，所以 <span class=\"gk-math\" data-tex=\"\\lvert BP\\rvert=\\sqrt{x_1^2+(y_1+1)^2}=\\lvert x_1\\rvert\\sqrt{1+k^2}\">\\lvert BP\\rvert=\\sqrt{x_1^2+(y_1+1)^2}=\\lvert x_1\\rvert\\sqrt{1+k^2}</span>由相同计算 <span class=\"gk-math\" data-tex=\"\\lvert BQ\\rvert=\\lvert x_2\\rvert\\sqrt{1+k^2}\">\\lvert BQ\\rvert=\\lvert x_2\\rvert\\sqrt{1+k^2}</span>，于是 <span class=\"gk-math\" data-tex=\"\\lvert BP\\rvert\\cdot\\lvert BQ\\rvert=\\lvert x_1x_2\\rvert(1+k^2)=1+k^2\">\\lvert BP\\rvert\\cdot\\lvert BQ\\rvert=\\lvert x_1x_2\\rvert(1+k^2)=1+k^2</span>. 又 <span class=\"gk-math\" data-tex=\"\\lvert BA\\rvert^2=(1-0)^2+(1+1)^2=5\">\\lvert BA\\rvert^2=(1-0)^2+(1+1)^2=5</span>，而 <span class=\"gk-math\" data-tex=\"1+k^2&gt;5\">1+k^2&gt;5</span> 等价于 <span class=\"gk-math\" data-tex=\"k^2&gt;4\">k^2&gt;4</span>，恰为 <span class=\"gk-math\" data-tex=\"\\Delta&gt;0\">\\Delta&gt;0</span> 的条件，所以 <span class=\"gk-math\" data-tex=\"\\lvert BP\\rvert\\cdot\\lvert BQ\\rvert&gt;\\lvert BA\\rvert^2\">\\lvert BP\\rvert\\cdot\\lvert BQ\\rvert&gt;\\lvert BA\\rvert^2</span>，故D正确. 综上选BCD.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q12","paperId":"2022-new_gaokao_paper_1","number":12,"type":"multiple","score":5,"lessonIds":["3.2","e2-5.2"],"difficulty":"挑战","hint":"先把两个复合函数为偶函数翻译成 f 和 g 的对称轴，再对 f 的对称关系求导。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x) 及其导函数 f'(x) 的定义域均为 \\R ，记 g(x)=f'(x) . 若 f\\left(\\frac32-2x\\right) ， g(2+x) 均为偶函数，则（ ） f(0)=0 g\\left(-\\frac12\\right)=0 f(-1)=f(4) g(-1)=g(2)","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 及其导函数 <span class=\"gk-math\" data-tex=\"f&#x27;(x)\">f&#x27;(x)</span> 的定义域均为 <span class=\"gk-math\" data-tex=\"\\R\">\\R</span>，记 <span class=\"gk-math\" data-tex=\"g(x)=f&#x27;(x)\">g(x)=f&#x27;(x)</span>. 若 <span class=\"gk-math\" data-tex=\"f\\left(\\frac32-2x\\right)\">f\\left(\\frac32-2x\\right)</span>，<span class=\"gk-math\" data-tex=\"g(2+x)\">g(2+x)</span> 均为偶函数，则（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"f(0)=0\">f(0)=0</span>","<span class=\"gk-math\" data-tex=\"g\\left(-\\frac12\\right)=0\">g\\left(-\\frac12\\right)=0</span>","<span class=\"gk-math\" data-tex=\"f(-1)=f(4)\">f(-1)=f(4)</span>","<span class=\"gk-math\" data-tex=\"g(-1)=g(2)\">g(-1)=g(2)</span>"],"answerHtml":"BC","answerKey":"BC","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"f\\left(\\frac{3}{2}-2x\\right)\">f\\left(\\frac{3}{2}-2x\\right)</span> 为偶函数，所以对一切 <span class=\"gk-math\" data-tex=\"x\\in\\R\">x\\in\\R</span> 有 <span class=\"gk-math\" data-tex=\"f\\left(\\frac{3}{2}+2x\\right)=f\\left(\\frac{3}{2}-2x\\right)\">f\\left(\\frac{3}{2}+2x\\right)=f\\left(\\frac{3}{2}-2x\\right)</span>. 令 <span class=\"gk-math\" data-tex=\"t=2x\">t=2x</span>，则 <span class=\"gk-math\" data-tex=\"f\\left(\\frac{3}{2}+t\\right)=f\\left(\\frac{3}{2}-t\\right)\">f\\left(\\frac{3}{2}+t\\right)=f\\left(\\frac{3}{2}-t\\right)</span>，即 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 关于 <span class=\"gk-math\" data-tex=\"x=\\frac{3}{2}\">x=\\frac{3}{2}</span> 对称，故 <span class=\"gk-math\" data-tex=\"f(3-x)=f(x)\">f(3-x)=f(x)</span>. 于是 <span class=\"gk-math\" data-tex=\"f(-1)=f(3-(-1))=f(4)\">f(-1)=f(3-(-1))=f(4)</span>，所以C正确. 因为 <span class=\"gk-math\" data-tex=\"g(2+x)\">g(2+x)</span> 为偶函数，所以 <span class=\"gk-math\" data-tex=\"g(2-x)=g(2+x)\">g(2-x)=g(2+x)</span>，即 <span class=\"gk-math\" data-tex=\"g(4-x)=g(x)\">g(4-x)=g(x)</span>，故 <span class=\"gk-math\" data-tex=\"g(x)\">g(x)</span> 关于 <span class=\"gk-math\" data-tex=\"x=2\">x=2</span> 对称. 对 <span class=\"gk-math\" data-tex=\"f(3-x)=f(x)\">f(3-x)=f(x)</span> 两边求导得 <span class=\"gk-math\" data-tex=\"-f&#x27;(3-x)=f&#x27;(x)\">-f&#x27;(3-x)=f&#x27;(x)</span>，即 <span class=\"gk-math\" data-tex=\"g(3-x)=-g(x)\">g(3-x)=-g(x)</span>. 由 <span class=\"gk-math\" data-tex=\"g(4-x)=g(x)\">g(4-x)=g(x)</span> 得 <span class=\"gk-math\" data-tex=\"g(x+1)=g(4-(x+1))=g(3-x)=-g(x)\">g(x+1)=g(4-(x+1))=g(3-x)=-g(x)</span>，所以 <span class=\"gk-math\" data-tex=\"g(x+1)=-g(x)\">g(x+1)=-g(x)</span>，进而 <span class=\"gk-math\" data-tex=\"g(x+2)=-g(x+1)=g(x)\">g(x+2)=-g(x+1)=g(x)</span>，即 <span class=\"gk-math\" data-tex=\"g\">g</span> 以 <span class=\"gk-math\" data-tex=\"2\">2</span> 为周期. 在 <span class=\"gk-math\" data-tex=\"g(3-x)=-g(x)\">g(3-x)=-g(x)</span> 中令 <span class=\"gk-math\" data-tex=\"x=\\frac{3}{2}\">x=\\frac{3}{2}</span> 得 <span class=\"gk-math\" data-tex=\"g\\left(\\frac{3}{2}\\right)=0\">g\\left(\\frac{3}{2}\\right)=0</span>，再由周期 <span class=\"gk-math\" data-tex=\"2\">2</span> 得 <span class=\"gk-math\" data-tex=\"g\\left(-\\frac{1}{2}\\right)=g\\left(\\frac{3}{2}\\right)=0\">g\\left(-\\frac{1}{2}\\right)=g\\left(\\frac{3}{2}\\right)=0</span>，所以B正确. 因为 <span class=\"gk-math\" data-tex=\"f(0)\">f(0)</span> 的值可平移而不破坏对称关系，不能由题设唯一确定，例如取 <span class=\"gk-math\" data-tex=\"g(x)=\\cos(\\pi x)\">g(x)=\\cos(\\pi x)</span> 及其原函数 <span class=\"gk-math\" data-tex=\"f(x)=\\frac{\\sin(\\pi x)}{\\pi}+C\">f(x)=\\frac{\\sin(\\pi x)}{\\pi}+C</span> 即满足全部对称条件，而 <span class=\"gk-math\" data-tex=\"C\">C</span> 任意，所以A不能成立. 因为由周期与 <span class=\"gk-math\" data-tex=\"g(x+1)=-g(x)\">g(x+1)=-g(x)</span> 得 <span class=\"gk-math\" data-tex=\"g(-1)=g(1)\">g(-1)=g(1)</span> 且 <span class=\"gk-math\" data-tex=\"g(2)=-g(1)\">g(2)=-g(1)</span>，所以 <span class=\"gk-math\" data-tex=\"g(-1)=g(2)\">g(-1)=g(2)</span> 当且仅当 <span class=\"gk-math\" data-tex=\"g(2)=0\">g(2)=0</span>，而上例中 <span class=\"gk-math\" data-tex=\"g(2)=1\\ne 0\">g(2)=1\\ne 0</span>，此时 <span class=\"gk-math\" data-tex=\"g(-1)=-1\\ne g(2)\">g(-1)=-1\\ne g(2)</span>，故D不成立. 综上选BC.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q13","paperId":"2022-new_gaokao_paper_1","number":13,"type":"fill","score":5,"lessonIds":["e3-6.3"],"difficulty":"基础","hint":"分成 (x+y)^8 与 −(y/x)(x+y)^8 两部分，分别找能产生 x²y⁶ 的项。","legacy":false,"legacyReason":"","searchText":"\\left(1-\\frac{y}{x}\\right)(x+y)^8 的展开式中 x^2y^6 的系数为 ________ （用数字作答）. ","questionHtml":"<span class=\"gk-math\" data-tex=\"\\left(1-\\frac{y}{x}\\right)(x+y)^8\">\\left(1-\\frac{y}{x}\\right)(x+y)^8</span> 的展开式中 <span class=\"gk-math\" data-tex=\"x^2y^6\">x^2y^6</span> 的系数为<span class=\"gk-blank\" aria-label=\"填空\">________</span>（用数字作答）.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"-28\">-28</span>","answerKey":"","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"\\left(1-\\frac{y}{x}\\right)(x+y)^8=(x+y)^8-\\frac{y}{x}(x+y)^8\">\\left(1-\\frac{y}{x}\\right)(x+y)^8=(x+y)^8-\\frac{y}{x}(x+y)^8</span>. 在 <span class=\"gk-math\" data-tex=\"(x+y)^8\">(x+y)^8</span> 中，<span class=\"gk-math\" data-tex=\"x^2y^6\">x^2y^6</span> 来自 <span class=\"gk-math\" data-tex=\"k=6\">k=6</span> 项，系数为 <span class=\"gk-math\" data-tex=\"\\mathrm C_8^6=28\">\\mathrm C_8^6=28</span>. 在 <span class=\"gk-math\" data-tex=\"\\frac{y}{x}(x+y)^8\">\\frac{y}{x}(x+y)^8</span> 中，要得到 <span class=\"gk-math\" data-tex=\"x^2y^6\">x^2y^6</span>，需 <span class=\"gk-math\" data-tex=\"(x+y)^8\">(x+y)^8</span> 提供 <span class=\"gk-math\" data-tex=\"x^3y^5\">x^3y^5</span>，即 <span class=\"gk-math\" data-tex=\"k=5\">k=5</span> 项，系数为 <span class=\"gk-math\" data-tex=\"\\mathrm C_8^5=56\">\\mathrm C_8^5=56</span>，带负号后贡献为 <span class=\"gk-math\" data-tex=\"-56\">-56</span>. 所以所求系数为 <span class=\"gk-math\" data-tex=\"28-56=-28\">28-56=-28</span>. 故答案为 <span class=\"gk-math\" data-tex=\"-28\">-28</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q14","paperId":"2022-new_gaokao_paper_1","number":14,"type":"fill","score":5,"lessonIds":["e1-2.5","e1-2.3"],"difficulty":"进阶","hint":"两个圆的半径分别为 1 和 4，可先设直线 y=kx+b，让两个圆心到直线的距离分别等于半径。","legacy":false,"legacyReason":"","searchText":"写出与圆 x^2+y^2=1 和 (x-3)^2+(y-4)^2=16 都相切的一条直线的方程 ________ . ","questionHtml":"写出与圆 <span class=\"gk-math\" data-tex=\"x^2+y^2=1\">x^2+y^2=1</span> 和 <span class=\"gk-math\" data-tex=\"(x-3)^2+(y-4)^2=16\">(x-3)^2+(y-4)^2=16</span> 都相切的一条直线的方程<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"x=-1\">x=-1</span>","answerKey":"","solutionHtml":"<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,448px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q14_solution_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q14_solution_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"432\" height=\"375\" style=\"aspect-ratio:432/375;width:100%\" loading=\"lazy\"></button></figure><br><br>记两圆圆心为 <span class=\"gk-math\" data-tex=\"O(0,0)\">O(0,0)</span>，<span class=\"gk-math\" data-tex=\"O_1(3,4)\">O_1(3,4)</span>，半径分别为 <span class=\"gk-math\" data-tex=\"1\">1</span>，<span class=\"gk-math\" data-tex=\"4\">4</span>. 因为 <span class=\"gk-math\" data-tex=\"\\lvert OO_1\\rvert=5=1+4\">\\lvert OO_1\\rvert=5=1+4</span>，所以两圆外切，共有三条公切线. 直线 <span class=\"gk-math\" data-tex=\"x=-1\">x=-1</span> 到 <span class=\"gk-math\" data-tex=\"O\">O</span> 的距离为 <span class=\"gk-math\" data-tex=\"1\">1</span>，到 <span class=\"gk-math\" data-tex=\"O_1\">O_1</span> 的距离为 <span class=\"gk-math\" data-tex=\"\\lvert 3-(-1)\\rvert=4\">\\lvert 3-(-1)\\rvert=4</span>，恰等于两圆半径，所以该直线与两圆都相切. 故可填 <span class=\"gk-math\" data-tex=\"x=-1\">x=-1</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q15","paperId":"2022-new_gaokao_paper_1","number":15,"type":"fill","score":5,"lessonIds":["e2-5.1","e2-5.3","2.3"],"difficulty":"进阶","hint":"设切点横坐标为 t，将切线经过原点写成 f(t)=tf′(t)，看所得二次方程何时有两个合适的根。","legacy":false,"legacyReason":"","searchText":"若曲线 y=(x+a)\\e^x 有两条过坐标原点的切线，则 a 的取值范围是 ________ . ","questionHtml":"若曲线 <span class=\"gk-math\" data-tex=\"y=(x+a)\\e^x\">y=(x+a)\\e^x</span> 有两条过坐标原点的切线，则 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围是<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"(-\\infty,-4)\\cup(0,+\\infty)\">(-\\infty,-4)\\cup(0,+\\infty)</span>","answerKey":"","solutionHtml":"设切点横坐标为 <span class=\"gk-math\" data-tex=\"x_0\">x_0</span>，记 <span class=\"gk-math\" data-tex=\"f(x)=(x+a)\\e^x\">f(x)=(x+a)\\e^x</span>，则 <span class=\"gk-math\" data-tex=\"f&#x27;(x)=(x+a+1)\\e^x\">f&#x27;(x)=(x+a+1)\\e^x</span>. 切线方程为 <span class=\"gk-math\" data-tex=\"y-(x_0+a)\\e^{x_0}=(x_0+a+1)\\e^{x_0}(x-x_0)\">y-(x_0+a)\\e^{x_0}=(x_0+a+1)\\e^{x_0}(x-x_0)</span>. 因为切线过原点，所以 <span class=\"gk-math\" data-tex=\"-(x_0+a)\\e^{x_0}=-(x_0+a+1)\\e^{x_0}x_0\">-(x_0+a)\\e^{x_0}=-(x_0+a+1)\\e^{x_0}x_0</span>. 又 <span class=\"gk-math\" data-tex=\"\\e^{x_0}\\ne 0\">\\e^{x_0}\\ne 0</span>，约去后得 <span class=\"gk-math\" data-tex=\"x_0+a=(x_0+a+1)x_0\">x_0+a=(x_0+a+1)x_0</span>，整理为 <span class=\"gk-math\" data-tex=\"x_0^2+ax_0-a=0\">x_0^2+ax_0-a=0</span>. 若 <span class=\"gk-math\" data-tex=\"x_0=1\">x_0=1</span>，上式化为 <span class=\"gk-math\" data-tex=\"1=0\">1=0</span>，不可能，所以切点横坐标满足 <span class=\"gk-math\" data-tex=\"x_0\\ne 1\">x_0\\ne 1</span>. 由 <span class=\"gk-math\" data-tex=\"x_0+a=(x_0+a+1)x_0\">x_0+a=(x_0+a+1)x_0</span> 得 <span class=\"gk-math\" data-tex=\"a=\\frac{x_0^2}{1-x_0}\">a=\\frac{x_0^2}{1-x_0}</span>，进而 <span class=\"gk-math\" data-tex=\"x_0+a+1=\\frac{1}{1-x_0}\">x_0+a+1=\\frac{1}{1-x_0}</span>，故切线斜率可记为 <span class=\"gk-math\" data-tex=\"m(x_0)=\\frac{\\e^{x_0}}{1-x_0}\">m(x_0)=\\frac{\\e^{x_0}}{1-x_0}</span>. 该二次方程的判别式为 <span class=\"gk-math\" data-tex=\"\\Delta=a^2+4a\">\\Delta=a^2+4a</span>. 当 <span class=\"gk-math\" data-tex=\"\\Delta&gt;0\">\\Delta&gt;0</span>，即 <span class=\"gk-math\" data-tex=\"a&lt;-4\">a&lt;-4</span> 或 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span> 时，方程有两个不同实根 <span class=\"gk-math\" data-tex=\"r_1\\ne r_2\">r_1\\ne r_2</span>，且乘积为 <span class=\"gk-math\" data-tex=\"-a\\ne 0\">-a\\ne 0</span>，故两根均非零，每根给出一条过原点的切线. 下证两根给出的切线不同. 当 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span> 时，两根一正一负；正根 <span class=\"gk-math\" data-tex=\"r=\\frac{-a+\\sqrt{a^2+4a}}{2}&lt;1\">r=\\frac{-a+\\sqrt{a^2+4a}}{2}&lt;1</span>，因为 <span class=\"gk-math\" data-tex=\"\\sqrt{a^2+4a}&lt;a+2\">\\sqrt{a^2+4a}&lt;a+2</span>，故两根皆小于 <span class=\"gk-math\" data-tex=\"1\">1</span>. 而 <span class=\"gk-math\" data-tex=\"m&#x27;(r)=\\frac{(2-r)\\e^r}{(1-r)^2}&gt;0\">m&#x27;(r)=\\frac{(2-r)\\e^r}{(1-r)^2}&gt;0</span>（<span class=\"gk-math\" data-tex=\"r&lt;1\">r&lt;1</span>），所以 <span class=\"gk-math\" data-tex=\"m\">m</span> 在 <span class=\"gk-math\" data-tex=\"(-\\infty,1)\">(-\\infty,1)</span> 上严格递增，两根斜率不同. 当 <span class=\"gk-math\" data-tex=\"a&lt;-4\">a&lt;-4</span> 时，两根之和与乘积均为 <span class=\"gk-math\" data-tex=\"-a&gt;4\">-a&gt;4</span>，故两根皆大于 <span class=\"gk-math\" data-tex=\"1\">1</span>；由 <span class=\"gk-math\" data-tex=\"(r_1-1)(r_2-1)=r_1r_2-(r_1+r_2)+1=1\">(r_1-1)(r_2-1)=r_1r_2-(r_1+r_2)+1=1</span>，记 <span class=\"gk-math\" data-tex=\"t_1=r_1-1\">t_1=r_1-1</span>，<span class=\"gk-math\" data-tex=\"t_2=r_2-1\">t_2=r_2-1</span>，则 <span class=\"gk-math\" data-tex=\"t_1t_2=1\">t_1t_2=1</span> 且 <span class=\"gk-math\" data-tex=\"t_1\\ne 1\">t_1\\ne 1</span>. 若两切线斜率相等，则 <span class=\"gk-math\" data-tex=\"\\frac{\\e^{r_1}}{1-r_1}=\\frac{\\e^{r_2}}{1-r_2}\">\\frac{\\e^{r_1}}{1-r_1}=\\frac{\\e^{r_2}}{1-r_2}</span>，即 <span class=\"gk-math\" data-tex=\"\\frac{\\e^{t_1}}{t_1}=\\frac{\\e^{t_2}}{t_2}\">\\frac{\\e^{t_1}}{t_1}=\\frac{\\e^{t_2}}{t_2}</span>，结合 <span class=\"gk-math\" data-tex=\"t_2=\\frac{1}{t_1}\">t_2=\\frac{1}{t_1}</span> 得 <span class=\"gk-math\" data-tex=\"t_1-\\frac{1}{t_1}=2\\ln t_1\">t_1-\\frac{1}{t_1}=2\\ln t_1</span>. 记 <span class=\"gk-math\" data-tex=\"\\eta(t)=t-\\frac1t-2\\ln t\">\\eta(t)=t-\\frac1t-2\\ln t</span>（<span class=\"gk-math\" data-tex=\"t&gt;0\">t&gt;0</span>，<span class=\"gk-math\" data-tex=\"t\\ne 1\">t\\ne 1</span>），则 <span class=\"gk-math\" data-tex=\"\\eta&#x27;(t)=\\left(1-\\frac1t\\right)^2&gt;0\">\\eta&#x27;(t)=\\left(1-\\frac1t\\right)^2&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"\\eta\">\\eta</span> 在 <span class=\"gk-math\" data-tex=\"(0,1)\">(0,1)</span> 和 <span class=\"gk-math\" data-tex=\"(1,+\\infty)\">(1,+\\infty)</span> 上分别严格递增，又 <span class=\"gk-math\" data-tex=\"\\eta(1)=0\">\\eta(1)=0</span>，故 <span class=\"gk-math\" data-tex=\"t-\\frac1t=2\\ln t\">t-\\frac1t=2\\ln t</span> 只有解 <span class=\"gk-math\" data-tex=\"t=1\">t=1</span>，与 <span class=\"gk-math\" data-tex=\"t_1\\ne 1\">t_1\\ne 1</span> 矛盾. 因此两根斜率不同，给出两条不同切线. 反之当 <span class=\"gk-math\" data-tex=\"\\Delta\\le 0\">\\Delta\\le 0</span> 时二次方程至多一根，至多一条过原点的切线. 故取值范围是 <span class=\"gk-math\" data-tex=\"(-\\infty,-4)\\cup(0,+\\infty)\">(-\\infty,-4)\\cup(0,+\\infty)</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q16","paperId":"2022-new_gaokao_paper_1","number":16,"type":"fill","score":5,"lessonIds":["e1-3.1","e1-2.1","6.4"],"difficulty":"挑战","hint":"由 e=1/2 得 c=a/2；先用上顶点与焦点的坐标确定 DE 的方向，再用焦点距离关系求周长。","legacy":false,"legacyReason":"","searchText":"已知椭圆 C:\\ \\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1 （ a>b>0 ）， C 的上顶点为 A ，两个焦点为 F_1 ， F_2 ，离心率为 \\frac12 . 过 F_1 且垂直于 AF_2 的直线与 C 交于 D ， E 两点， |DE|=6 ，则 \\triangle ADE 的周长是 ________ . ","questionHtml":"已知椭圆 <span class=\"gk-math\" data-tex=\"C:\\ \\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1\">C:\\ \\frac{x^2}{a^2}+\\frac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;b&gt;0\">a&gt;b&gt;0</span>），<span class=\"gk-math\" data-tex=\"C\">C</span> 的上顶点为 <span class=\"gk-math\" data-tex=\"A\">A</span>，两个焦点为 <span class=\"gk-math\" data-tex=\"F_1\">F_1</span>，<span class=\"gk-math\" data-tex=\"F_2\">F_2</span>，离心率为 <span class=\"gk-math\" data-tex=\"\\frac12\">\\frac12</span>. 过 <span class=\"gk-math\" data-tex=\"F_1\">F_1</span> 且垂直于 <span class=\"gk-math\" data-tex=\"AF_2\">AF_2</span> 的直线与 <span class=\"gk-math\" data-tex=\"C\">C</span> 交于 <span class=\"gk-math\" data-tex=\"D\">D</span>，<span class=\"gk-math\" data-tex=\"E\">E</span> 两点，<span class=\"gk-math\" data-tex=\"|DE|=6\">|DE|=6</span>，则 <span class=\"gk-math\" data-tex=\"\\triangle ADE\">\\triangle ADE</span> 的周长是<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"13\">13</span>","answerKey":"","solutionHtml":"因为离心率 <span class=\"gk-math\" data-tex=\"e=\\frac{c}{a}=\\frac{1}{2}\">e=\\frac{c}{a}=\\frac{1}{2}</span>，所以 <span class=\"gk-math\" data-tex=\"a=2c\">a=2c</span>，<span class=\"gk-math\" data-tex=\"b^2=a^2-c^2=3c^2\">b^2=a^2-c^2=3c^2</span>，椭圆方程为 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{4c^2}+\\frac{y^2}{3c^2}=1\">\\frac{x^2}{4c^2}+\\frac{y^2}{3c^2}=1</span>. 记上顶点为 <span class=\"gk-math\" data-tex=\"A(0,b)\">A(0,b)</span>，焦点为 <span class=\"gk-math\" data-tex=\"F_1(-c,0)\">F_1(-c,0)</span>，<span class=\"gk-math\" data-tex=\"F_2(c,0)\">F_2(c,0)</span>. 因为 <span class=\"gk-math\" data-tex=\"\\lvert AF_1\\rvert=\\lvert AF_2\\rvert=a\">\\lvert AF_1\\rvert=\\lvert AF_2\\rvert=a</span> 且 <span class=\"gk-math\" data-tex=\"\\lvert F_1F_2\\rvert=2c=a\">\\lvert F_1F_2\\rvert=2c=a</span>，所以 <span class=\"gk-math\" data-tex=\"\\triangle AF_1F_2\">\\triangle AF_1F_2</span> 为边长 <span class=\"gk-math\" data-tex=\"a\">a</span> 的等边三角形. 过 <span class=\"gk-math\" data-tex=\"F_1\">F_1</span> 且垂直于 <span class=\"gk-math\" data-tex=\"AF_2\">AF_2</span> 的直线即等边三角形从 <span class=\"gk-math\" data-tex=\"F_1\">F_1</span> 向对边 <span class=\"gk-math\" data-tex=\"AF_2\">AF_2</span> 作的高，也是 <span class=\"gk-math\" data-tex=\"AF_2\">AF_2</span> 的垂直平分线，故其上任一点到 <span class=\"gk-math\" data-tex=\"A\">A</span> 与到 <span class=\"gk-math\" data-tex=\"F_2\">F_2</span> 距离相等，特别有 <span class=\"gk-math\" data-tex=\"\\lvert AD\\rvert=\\lvert DF_2\\rvert\">\\lvert AD\\rvert=\\lvert DF_2\\rvert</span>，<span class=\"gk-math\" data-tex=\"\\lvert AE\\rvert=\\lvert EF_2\\rvert\">\\lvert AE\\rvert=\\lvert EF_2\\rvert</span>. 因为 <span class=\"gk-math\" data-tex=\"AF_2\">AF_2</span> 斜率为 <span class=\"gk-math\" data-tex=\"-\\frac{b}{c}=-\\sqrt{3}\">-\\frac{b}{c}=-\\sqrt{3}</span>，所以 <span class=\"gk-math\" data-tex=\"DE\">DE</span> 斜率为 <span class=\"gk-math\" data-tex=\"\\frac{1}{\\sqrt{3}}\">\\frac{1}{\\sqrt{3}}</span>，方程为 <span class=\"gk-math\" data-tex=\"y=\\frac{1}{\\sqrt{3}}(x+c)\">y=\\frac{1}{\\sqrt{3}}(x+c)</span>. 联立椭圆方程得 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{4c^2}+\\frac{(x+c)^2}{9c^2}=1\">\\frac{x^2}{4c^2}+\\frac{(x+c)^2}{9c^2}=1</span>，即 <span class=\"gk-math\" data-tex=\"13x^2+8cx-32c^2=0\">13x^2+8cx-32c^2=0</span>. 设 <span class=\"gk-math\" data-tex=\"D\">D</span>，<span class=\"gk-math\" data-tex=\"E\">E</span> 横坐标为 <span class=\"gk-math\" data-tex=\"x_D\">x_D</span>，<span class=\"gk-math\" data-tex=\"x_E\">x_E</span>，则 <span class=\"gk-math\" data-tex=\"x_D+x_E=-\\frac{8c}{13}\">x_D+x_E=-\\frac{8c}{13}</span>，<span class=\"gk-math\" data-tex=\"x_Dx_E=-\\frac{32c^2}{13}\">x_Dx_E=-\\frac{32c^2}{13}</span>. 由弦长公式得 <span class=\"gk-math\" data-tex=\"\\lvert DE\\rvert=\\sqrt{1+\\frac{1}{3}}\\lvert x_D-x_E\\rvert=\\frac{2}{\\sqrt{3}}\\sqrt{(x_D+x_E)^2-4x_Dx_E}=\\frac{2}{\\sqrt{3}}\\sqrt{\\frac{64c^2}{169}+\\frac{128c^2}{13}}=\\frac{48}{13}c\">\\lvert DE\\rvert=\\sqrt{1+\\frac{1}{3}}\\lvert x_D-x_E\\rvert=\\frac{2}{\\sqrt{3}}\\sqrt{(x_D+x_E)^2-4x_Dx_E}=\\frac{2}{\\sqrt{3}}\\sqrt{\\frac{64c^2}{169}+\\frac{128c^2}{13}}=\\frac{48}{13}c</span>. 由 <span class=\"gk-math\" data-tex=\"\\lvert DE\\rvert=6\">\\lvert DE\\rvert=6</span> 得 <span class=\"gk-math\" data-tex=\"c=\\frac{13}{8}\">c=\\frac{13}{8}</span>，从而 <span class=\"gk-math\" data-tex=\"a=2c=\\frac{13}{4}\">a=2c=\\frac{13}{4}</span>. 因为 <span class=\"gk-math\" data-tex=\"F_1\">F_1</span> 在椭圆内，<span class=\"gk-math\" data-tex=\"D\">D</span>，<span class=\"gk-math\" data-tex=\"E\">E</span> 分居 <span class=\"gk-math\" data-tex=\"F_1\">F_1</span> 两侧，所以 <span class=\"gk-math\" data-tex=\"\\lvert DE\\rvert=\\lvert DF_1\\rvert+\\lvert EF_1\\rvert\">\\lvert DE\\rvert=\\lvert DF_1\\rvert+\\lvert EF_1\\rvert</span>. 于是 <span class=\"gk-math\" data-tex=\"\\triangle ADE\">\\triangle ADE</span> 周长等于 <span class=\"gk-math\" data-tex=\"(\\lvert AD\\rvert+\\lvert AE\\rvert)+\\lvert DE\\rvert=(\\lvert DF_2\\rvert+\\lvert DF_1\\rvert)+(\\lvert EF_2\\rvert+\\lvert EF_1\\rvert)=2a+2a=4a=13\">(\\lvert AD\\rvert+\\lvert AE\\rvert)+\\lvert DE\\rvert=(\\lvert DF_2\\rvert+\\lvert DF_1\\rvert)+(\\lvert EF_2\\rvert+\\lvert EF_1\\rvert)=2a+2a=4a=13</span>. 故答案为 <span class=\"gk-math\" data-tex=\"13\">13</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q17","paperId":"2022-new_gaokao_paper_1","number":17,"type":"written","score":10,"lessonIds":["e2-4.1","e2-4.2"],"difficulty":"进阶","hint":"先由首项算 S₁/a₁=1，写出 S_n/a_n 的等差通项，再用相邻两式相减。","legacy":false,"legacyReason":"","searchText":"记 S_n 为数列 \\{a_n\\} 的前 n 项和，已知 a_1=1 ，数列 \\left\\{\\frac{S_n}{a_n}\\right\\} 是公差为 \\frac13 的等差数列. 求 \\{a_n\\} 的通项公式； 证明： \\frac1{a_1}+\\frac1{a_2}+\\cdots+\\frac1{a_n}<2 . ","questionHtml":"记 <span class=\"gk-math\" data-tex=\"S_n\">S_n</span> 为数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和，已知 <span class=\"gk-math\" data-tex=\"a_1=1\">a_1=1</span>，数列 <span class=\"gk-math\" data-tex=\"\\left\\{\\frac{S_n}{a_n}\\right\\}\">\\left\\{\\frac{S_n}{a_n}\\right\\}</span> 是公差为 <span class=\"gk-math\" data-tex=\"\\frac13\">\\frac13</span> 的等差数列.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的通项公式；</li><li>证明：<span class=\"gk-math\" data-tex=\"\\frac1{a_1}+\\frac1{a_2}+\\cdots+\\frac1{a_n}&lt;2\">\\frac1{a_1}+\\frac1{a_2}+\\cdots+\\frac1{a_n}&lt;2</span>.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>因为 <span class=\"gk-math\" data-tex=\"\\frac{S_1}{a_1}=1\">\\frac{S_1}{a_1}=1</span>，且 <span class=\"gk-math\" data-tex=\"\\left\\{\\frac{S_n}{a_n}\\right\\}\">\\left\\{\\frac{S_n}{a_n}\\right\\}</span> 是公差为 <span class=\"gk-math\" data-tex=\"\\frac13\">\\frac13</span> 的等差数列，所以 <span class=\"gk-math\" data-tex=\"\\frac{S_n}{a_n}=1+\\frac{n-1}{3}=\\frac{n+2}{3}\">\\frac{S_n}{a_n}=1+\\frac{n-1}{3}=\\frac{n+2}{3}</span>. 于是 <span class=\"gk-math\" data-tex=\"S_n=\\frac{n+2}{3}a_n\">S_n=\\frac{n+2}{3}a_n</span>. 当 <span class=\"gk-math\" data-tex=\"n\\ge 2\">n\\ge 2</span> 时，<span class=\"gk-math\" data-tex=\"S_{n-1}=\\frac{n+1}{3}a_{n-1}\">S_{n-1}=\\frac{n+1}{3}a_{n-1}</span>，所以 <span class=\"gk-math\" data-tex=\"a_n=S_n-S_{n-1}=\\frac{n+2}{3}a_n-\\frac{n+1}{3}a_{n-1}\">a_n=S_n-S_{n-1}=\\frac{n+2}{3}a_n-\\frac{n+1}{3}a_{n-1}</span>，整理得 <span class=\"gk-math\" data-tex=\"(n-1)a_n=(n+1)a_{n-1}\">(n-1)a_n=(n+1)a_{n-1}</span>. 因为 <span class=\"gk-math\" data-tex=\"n\\ge 2\">n\\ge 2</span> 时 <span class=\"gk-math\" data-tex=\"n-1&gt;0\">n-1&gt;0</span>，且由 <span class=\"gk-math\" data-tex=\"a_1=1\">a_1=1</span> 递推，所以各 <span class=\"gk-math\" data-tex=\"a_n\\ne 0\">a_n\\ne 0</span>，所以 <span class=\"gk-math\" data-tex=\"\\frac{a_n}{a_{n-1}}=\\frac{n+1}{n-1}\">\\frac{a_n}{a_{n-1}}=\\frac{n+1}{n-1}</span>（<span class=\"gk-math\" data-tex=\"n\\ge 2\">n\\ge 2</span>）. 因此 <span class=\"gk-math\" data-tex=\"a_n=a_1\\cdot \\frac{a_2}{a_1}\\cdot \\frac{a_3}{a_2}\\cdots \\frac{a_n}{a_{n-1}}=1\\cdot \\frac31\\cdot \\frac42\\cdots \\frac{n}{n-2}\\cdot \\frac{n+1}{n-1}=\\frac{n(n+1)}{2}\">a_n=a_1\\cdot \\frac{a_2}{a_1}\\cdot \\frac{a_3}{a_2}\\cdots \\frac{a_n}{a_{n-1}}=1\\cdot \\frac31\\cdot \\frac42\\cdots \\frac{n}{n-2}\\cdot \\frac{n+1}{n-1}=\\frac{n(n+1)}{2}</span>. 又当 <span class=\"gk-math\" data-tex=\"n=1\">n=1</span> 时，<span class=\"gk-math\" data-tex=\"\\frac{1\\cdot 2}{2}=1=a_1\">\\frac{1\\cdot 2}{2}=1=a_1</span>，所以对一切正整数 <span class=\"gk-math\" data-tex=\"n\">n</span>，<span class=\"gk-math\" data-tex=\"a_n=\\frac{n(n+1)}{2}\">a_n=\\frac{n(n+1)}{2}</span>.</li><li>由（1）知 <span class=\"gk-math\" data-tex=\"\\frac1{a_n}=\\frac{2}{n(n+1)}=2\\left(\\frac1n-\\frac1{n+1}\\right)\">\\frac1{a_n}=\\frac{2}{n(n+1)}=2\\left(\\frac1n-\\frac1{n+1}\\right)</span>. 因此 <span class=\"gk-math\" data-tex=\"\\frac1{a_1}+\\frac1{a_2}+\\cdots+\\frac1{a_n}=2\\sum_{k=1}^n\\left(\\frac1k-\\frac1{k+1}\\right)=2\\left(1-\\frac1{n+1}\\right)&lt;2\">\\frac1{a_1}+\\frac1{a_2}+\\cdots+\\frac1{a_n}=2\\sum_{k=1}^n\\left(\\frac1k-\\frac1{k+1}\\right)=2\\left(1-\\frac1{n+1}\\right)&lt;2</span>. 证毕.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q18","paperId":"2022-new_gaokao_paper_1","number":18,"type":"written","score":12,"lessonIds":["5.5","6.4","2.2"],"difficulty":"挑战","hint":"右边先用二倍角公式化成 tanB，左边可配合半角关系，找出 A 与 B 的联系。","legacy":false,"legacyReason":"","searchText":"记 \\triangle ABC 的内角 A ， B ， C 的对边分别为 a ， b ， c ，已知 \\frac{\\cos A}{1+\\sin A}=\\frac{\\sin 2B}{1+\\cos 2B} . 若 C=\\frac{2\\pi}{3} ，求 B ； 求 \\frac{a^2+b^2}{c^2} 的最小值. ","questionHtml":"记 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 的内角 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>，<span class=\"gk-math\" data-tex=\"C\">C</span> 的对边分别为 <span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"b\">b</span>，<span class=\"gk-math\" data-tex=\"c\">c</span>，已知 <span class=\"gk-math\" data-tex=\"\\frac{\\cos A}{1+\\sin A}=\\frac{\\sin 2B}{1+\\cos 2B}\">\\frac{\\cos A}{1+\\sin A}=\\frac{\\sin 2B}{1+\\cos 2B}</span>.<br><br><ol class=\"gk-subparts\"><li>若 <span class=\"gk-math\" data-tex=\"C=\\frac{2\\pi}{3}\">C=\\frac{2\\pi}{3}</span>，求 <span class=\"gk-math\" data-tex=\"B\">B</span>；</li><li>求 <span class=\"gk-math\" data-tex=\"\\frac{a^2+b^2}{c^2}\">\\frac{a^2+b^2}{c^2}</span> 的最小值.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>因为 <span class=\"gk-math\" data-tex=\"B\\in(0,\\pi)\">B\\in(0,\\pi)</span> 且 <span class=\"gk-math\" data-tex=\"1+\\cos 2B=2\\cos^2B\">1+\\cos 2B=2\\cos^2B</span>，所以 <span class=\"gk-math\" data-tex=\"B\\ne \\frac{\\pi}{2}\">B\\ne \\frac{\\pi}{2}</span>，且 <span class=\"gk-math\" data-tex=\"\\frac{\\sin 2B}{1+\\cos 2B}=\\frac{2\\sin B\\cos B}{2\\cos^2B}=\\frac{\\sin B}{\\cos B}\">\\frac{\\sin 2B}{1+\\cos 2B}=\\frac{2\\sin B\\cos B}{2\\cos^2B}=\\frac{\\sin B}{\\cos B}</span>. 所以已知条件化为 <span class=\"gk-math\" data-tex=\"\\frac{\\cos A}{1+\\sin A}=\\frac{\\sin B}{\\cos B}\">\\frac{\\cos A}{1+\\sin A}=\\frac{\\sin B}{\\cos B}</span>，即 <span class=\"gk-math\" data-tex=\"\\cos A\\cos B=\\sin B(1+\\sin A)\">\\cos A\\cos B=\\sin B(1+\\sin A)</span>，整理得 <span class=\"gk-math\" data-tex=\"\\cos A\\cos B-\\sin A\\sin B=\\sin B\">\\cos A\\cos B-\\sin A\\sin B=\\sin B</span>，即 <span class=\"gk-math\" data-tex=\"\\cos(A+B)=\\sin B\">\\cos(A+B)=\\sin B</span>. 因为 <span class=\"gk-math\" data-tex=\"A+B=\\pi-C\">A+B=\\pi-C</span>，所以 <span class=\"gk-math\" data-tex=\"\\sin B=-\\cos C\">\\sin B=-\\cos C</span>. 当 <span class=\"gk-math\" data-tex=\"C=\\frac{2\\pi}{3}\">C=\\frac{2\\pi}{3}</span> 时， <span class=\"gk-math\" data-tex=\"\\sin B=-\\cos\\frac{2\\pi}{3}=\\frac12\">\\sin B=-\\cos\\frac{2\\pi}{3}=\\frac12</span>. 又此时 <span class=\"gk-math\" data-tex=\"A+B=\\frac{\\pi}{3}\">A+B=\\frac{\\pi}{3}</span>，所以 <span class=\"gk-math\" data-tex=\"0&lt;B&lt;\\frac{\\pi}{3}\">0&lt;B&lt;\\frac{\\pi}{3}</span>，故 <span class=\"gk-math\" data-tex=\"B=\\frac{\\pi}{6}\">B=\\frac{\\pi}{6}</span>.</li><li>由（1）已证 <span class=\"gk-math\" data-tex=\"\\sin B=-\\cos C&gt;0\">\\sin B=-\\cos C&gt;0</span>，因为 <span class=\"gk-math\" data-tex=\"B\\in(0,\\pi)\">B\\in(0,\\pi)</span>，<span class=\"gk-math\" data-tex=\"C\\in(0,\\pi)\">C\\in(0,\\pi)</span>，所以 <span class=\"gk-math\" data-tex=\"\\frac{\\pi}{2}&lt;C&lt;\\pi\">\\frac{\\pi}{2}&lt;C&lt;\\pi</span>，<span class=\"gk-math\" data-tex=\"0&lt;B&lt;\\frac{\\pi}{2}\">0&lt;B&lt;\\frac{\\pi}{2}</span>. 又 <span class=\"gk-math\" data-tex=\"-\\cos C=\\sin\\left(C-\\frac{\\pi}{2}\\right)\">-\\cos C=\\sin\\left(C-\\frac{\\pi}{2}\\right)</span>，所以 <span class=\"gk-math\" data-tex=\"\\sin B=\\sin\\left(C-\\frac{\\pi}{2}\\right)\">\\sin B=\\sin\\left(C-\\frac{\\pi}{2}\\right)</span>. 因为 <span class=\"gk-math\" data-tex=\"B\\in\\left(0,\\frac{\\pi}{2}\\right)\">B\\in\\left(0,\\frac{\\pi}{2}\\right)</span>，<span class=\"gk-math\" data-tex=\"C-\\frac{\\pi}{2}\\in\\left(0,\\frac{\\pi}{2}\\right)\">C-\\frac{\\pi}{2}\\in\\left(0,\\frac{\\pi}{2}\\right)</span>，而正弦函数在 <span class=\"gk-math\" data-tex=\"\\left(0,\\frac{\\pi}{2}\\right)\">\\left(0,\\frac{\\pi}{2}\\right)</span> 上单调递增，所以 <span class=\"gk-math\" data-tex=\"B=C-\\frac{\\pi}{2}\">B=C-\\frac{\\pi}{2}</span>，即 <span class=\"gk-math\" data-tex=\"C=\\frac{\\pi}{2}+B\">C=\\frac{\\pi}{2}+B</span>. 从而 <span class=\"gk-math\" data-tex=\"A=\\pi-B-C=\\frac{\\pi}{2}-2B\">A=\\pi-B-C=\\frac{\\pi}{2}-2B</span>. 因为 <span class=\"gk-math\" data-tex=\"A&gt;0\">A&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"B&lt;\\frac{\\pi}{4}\">B&lt;\\frac{\\pi}{4}</span>，结合 <span class=\"gk-math\" data-tex=\"B&gt;0\">B&gt;0</span> 得 <span class=\"gk-math\" data-tex=\"B\\in\\left(0,\\frac{\\pi}{4}\\right)\">B\\in\\left(0,\\frac{\\pi}{4}\\right)</span>，<span class=\"gk-math\" data-tex=\"C\\in\\left(\\frac{\\pi}{2},\\frac{3\\pi}{4}\\right)\">C\\in\\left(\\frac{\\pi}{2},\\frac{3\\pi}{4}\\right)</span>. 由正弦定理， <span class=\"gk-math\" data-tex=\"\\frac{a^2+b^2}{c^2}=\\frac{\\sin^2A+\\sin^2B}{\\sin^2C}\">\\frac{a^2+b^2}{c^2}=\\frac{\\sin^2A+\\sin^2B}{\\sin^2C}</span>. 因为 <span class=\"gk-math\" data-tex=\"\\sin A=\\sin\\left(\\frac{\\pi}{2}-2B\\right)=\\cos 2B\">\\sin A=\\sin\\left(\\frac{\\pi}{2}-2B\\right)=\\cos 2B</span>，<span class=\"gk-math\" data-tex=\"\\sin C=\\sin\\left(\\frac{\\pi}{2}+B\\right)=\\cos B\">\\sin C=\\sin\\left(\\frac{\\pi}{2}+B\\right)=\\cos B</span>，所以 <span class=\"gk-math\" data-tex=\"\\frac{a^2+b^2}{c^2}=\\frac{\\cos^22B+\\sin^2B}{\\cos^2B}\">\\frac{a^2+b^2}{c^2}=\\frac{\\cos^22B+\\sin^2B}{\\cos^2B}</span>. 又 <span class=\"gk-math\" data-tex=\"\\cos 2B=2\\cos^2B-1\">\\cos 2B=2\\cos^2B-1</span>，<span class=\"gk-math\" data-tex=\"\\sin^2B=1-\\cos^2B\">\\sin^2B=1-\\cos^2B</span>，所以分子为 <span class=\"gk-math\" data-tex=\"\\left(2\\cos^2B-1\\right)^2+1-\\cos^2B\">\\left(2\\cos^2B-1\\right)^2+1-\\cos^2B</span>，即 <span class=\"gk-math\" data-tex=\"\\frac{a^2+b^2}{c^2}=4\\cos^2B+\\frac{2}{\\cos^2B}-5\">\\frac{a^2+b^2}{c^2}=4\\cos^2B+\\frac{2}{\\cos^2B}-5</span>. 记 <span class=\"gk-math\" data-tex=\"t=\\cos^2B\">t=\\cos^2B</span>，因为 <span class=\"gk-math\" data-tex=\"B\\in\\left(0,\\frac{\\pi}{4}\\right)\">B\\in\\left(0,\\frac{\\pi}{4}\\right)</span>，所以 <span class=\"gk-math\" data-tex=\"t\\in\\left(\\frac12,1\\right)\">t\\in\\left(\\frac12,1\\right)</span>. 于是 <span class=\"gk-math\" data-tex=\"\\frac{a^2+b^2}{c^2}=4t+\\frac{2}{t}-5\">\\frac{a^2+b^2}{c^2}=4t+\\frac{2}{t}-5</span>. 因为 <span class=\"gk-math\" data-tex=\"4t&gt;0\">4t&gt;0</span>，<span class=\"gk-math\" data-tex=\"\\frac{2}{t}&gt;0\">\\frac{2}{t}&gt;0</span>，由均值不等式， <span class=\"gk-math\" data-tex=\"4t+\\frac{2}{t}\\ge 2\\sqrt{4t\\cdot \\frac{2}{t}}=2\\sqrt8=4\\sqrt2\">4t+\\frac{2}{t}\\ge 2\\sqrt{4t\\cdot \\frac{2}{t}}=2\\sqrt8=4\\sqrt2</span>，所以 <span class=\"gk-math\" data-tex=\"\\frac{a^2+b^2}{c^2}\\ge 4\\sqrt2-5\">\\frac{a^2+b^2}{c^2}\\ge 4\\sqrt2-5</span>. 当且仅当 <span class=\"gk-math\" data-tex=\"4t=\\frac{2}{t}\">4t=\\frac{2}{t}</span>，即 <span class=\"gk-math\" data-tex=\"t=\\frac{\\sqrt2}{2}\">t=\\frac{\\sqrt2}{2}</span> 时取等号. 因为 <span class=\"gk-math\" data-tex=\"\\frac12&lt;\\frac{\\sqrt2}{2}&lt;1\">\\frac12&lt;\\frac{\\sqrt2}{2}&lt;1</span>，故该 <span class=\"gk-math\" data-tex=\"t\">t</span> 落在 <span class=\"gk-math\" data-tex=\"\\left(\\frac12,1\\right)\">\\left(\\frac12,1\\right)</span> 内可取，对应 <span class=\"gk-math\" data-tex=\"B\\in\\left(0,\\frac{\\pi}{4}\\right)\">B\\in\\left(0,\\frac{\\pi}{4}\\right)</span> 存在. 所以 <span class=\"gk-math\" data-tex=\"\\frac{a^2+b^2}{c^2}\">\\frac{a^2+b^2}{c^2}</span> 的最小值为 <span class=\"gk-math\" data-tex=\"4\\sqrt2-5\">4\\sqrt2-5</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q19","paperId":"2022-new_gaokao_paper_1","number":19,"type":"written","score":12,"lessonIds":["8.3","8.6","e1-1.4"],"difficulty":"进阶","hint":"第一问先把 A−A₁BC 看作棱柱体积的三分之一，再用已知三角形面积倒求高。","legacy":false,"legacyReason":"","searchText":"如图，直三棱柱 ABC-A_1B_1C_1 的体积为 4 ， \\triangle A_1BC 的面积为 2\\sqrt2 . 求 A 到平面 A_1BC 的距离； 设 D 为 A_1C 的中点， AA_1=AB ，平面 A_1BC\\perp 平面 ABB_1A_1 ，求二面角 A-BD-C 的正弦值. ","questionHtml":"如图，直三棱柱 <span class=\"gk-math\" data-tex=\"ABC-A_1B_1C_1\">ABC-A_1B_1C_1</span> 的体积为 <span class=\"gk-math\" data-tex=\"4\">4</span>，<span class=\"gk-math\" data-tex=\"\\triangle A_1BC\">\\triangle A_1BC</span> 的面积为 <span class=\"gk-math\" data-tex=\"2\\sqrt2\">2\\sqrt2</span>.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"A\">A</span> 到平面 <span class=\"gk-math\" data-tex=\"A_1BC\">A_1BC</span> 的距离；</li><li>设 <span class=\"gk-math\" data-tex=\"D\">D</span> 为 <span class=\"gk-math\" data-tex=\"A_1C\">A_1C</span> 的中点，<span class=\"gk-math\" data-tex=\"AA_1=AB\">AA_1=AB</span>，平面 <span class=\"gk-math\" data-tex=\"A_1BC\\perp\">A_1BC\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"ABB_1A_1\">ABB_1A_1</span>，求二面角 <span class=\"gk-math\" data-tex=\"A-BD-C\">A-BD-C</span> 的正弦值.</li></ol><br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,453px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q19_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q19_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"437\" height=\"441\" style=\"aspect-ratio:437/441;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,290px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q19_solution_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/new_gaokao_paper_1/q19_solution_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"274\" height=\"280\" style=\"aspect-ratio:274/280;width:100%\" loading=\"lazy\"></button></figure> <ol class=\"gk-subparts\"><li>设点 <span class=\"gk-math\" data-tex=\"A\">A</span> 到平面 <span class=\"gk-math\" data-tex=\"A_1BC\">A_1BC</span> 的距离为 <span class=\"gk-math\" data-tex=\"h\">h</span>，则 <span class=\"gk-math\" data-tex=\"V_{A-A_1BC}=\\frac13S_{\\triangle A_1BC}\\cdot h=\\frac13\\cdot 2\\sqrt2\\cdot h=\\frac{2\\sqrt2}{3}h\">V_{A-A_1BC}=\\frac13S_{\\triangle A_1BC}\\cdot h=\\frac13\\cdot 2\\sqrt2\\cdot h=\\frac{2\\sqrt2}{3}h</span>. 又三棱锥 <span class=\"gk-math\" data-tex=\"A-A_1BC\">A-A_1BC</span> 与三棱锥 <span class=\"gk-math\" data-tex=\"A_1-ABC\">A_1-ABC</span> 为同一几何体，而 <span class=\"gk-math\" data-tex=\"V_{A_1-ABC}=\\frac13V_{ABC-A_1B_1C_1}=\\frac43\">V_{A_1-ABC}=\\frac13V_{ABC-A_1B_1C_1}=\\frac43</span>，所以 <span class=\"gk-math\" data-tex=\"V_{A-A_1BC}=\\frac43\">V_{A-A_1BC}=\\frac43</span>. 解得 <span class=\"gk-math\" data-tex=\"h=\\sqrt2\">h=\\sqrt2</span>. 所以点 <span class=\"gk-math\" data-tex=\"A\">A</span> 到平面 <span class=\"gk-math\" data-tex=\"A_1BC\">A_1BC</span> 的距离为 <span class=\"gk-math\" data-tex=\"\\sqrt2\">\\sqrt2</span>.</li><li>取 <span class=\"gk-math\" data-tex=\"A_1B\">A_1B</span> 的中点 <span class=\"gk-math\" data-tex=\"E\">E</span>，连接 <span class=\"gk-math\" data-tex=\"AE\">AE</span>，因为 <span class=\"gk-math\" data-tex=\"AA_1=AB\">AA_1=AB</span>，所以 <span class=\"gk-math\" data-tex=\"AE\\perp A_1B\">AE\\perp A_1B</span>. 又平面 <span class=\"gk-math\" data-tex=\"A_1BC\\perp\">A_1BC\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"ABB_1A_1\">ABB_1A_1</span>，交线为 <span class=\"gk-math\" data-tex=\"A_1B\">A_1B</span>，且 <span class=\"gk-math\" data-tex=\"AE\\subset\">AE\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"ABB_1A_1\">ABB_1A_1</span>，所以 <span class=\"gk-math\" data-tex=\"AE\\perp\">AE\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"A_1BC\">A_1BC</span>. 因此 <span class=\"gk-math\" data-tex=\"AE\">AE</span> 即为点 <span class=\"gk-math\" data-tex=\"A\">A</span> 到平面 <span class=\"gk-math\" data-tex=\"A_1BC\">A_1BC</span> 的距离，由（1）得 <span class=\"gk-math\" data-tex=\"AE=\\sqrt2\">AE=\\sqrt2</span>. 在直三棱柱中，<span class=\"gk-math\" data-tex=\"BB_1\\perp\">BB_1\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"ABC\">ABC</span>，因为 <span class=\"gk-math\" data-tex=\"BC\\subset\">BC\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"ABC\">ABC</span>，所以 <span class=\"gk-math\" data-tex=\"BB_1\\perp BC\">BB_1\\perp BC</span>. 又 <span class=\"gk-math\" data-tex=\"AE\\perp\">AE\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"A_1BC\">A_1BC</span>，<span class=\"gk-math\" data-tex=\"BC\\subset\">BC\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"A_1BC\">A_1BC</span>，所以 <span class=\"gk-math\" data-tex=\"AE\\perp BC\">AE\\perp BC</span>. 因为 <span class=\"gk-math\" data-tex=\"AE\">AE</span>，<span class=\"gk-math\" data-tex=\"BB_1\\subset\">BB_1\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"ABB_1A_1\">ABB_1A_1</span> 且相交，所以 <span class=\"gk-math\" data-tex=\"BC\\perp\">BC\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"ABB_1A_1\">ABB_1A_1</span>. 因此 <span class=\"gk-math\" data-tex=\"BC\\perp AB\">BC\\perp AB</span>，<span class=\"gk-math\" data-tex=\"BC\\perp BB_1\">BC\\perp BB_1</span>，而 <span class=\"gk-math\" data-tex=\"AB\\perp BB_1\">AB\\perp BB_1</span>，故 <span class=\"gk-math\" data-tex=\"BC\">BC</span>，<span class=\"gk-math\" data-tex=\"BA\">BA</span>，<span class=\"gk-math\" data-tex=\"BB_1\">BB_1</span> 两两垂直. 以 <span class=\"gk-math\" data-tex=\"B\">B</span> 为原点，分别以 <span class=\"gk-math\" data-tex=\"BC\">BC</span>，<span class=\"gk-math\" data-tex=\"BA\">BA</span>，<span class=\"gk-math\" data-tex=\"BB_1\">BB_1</span> 为 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴、<span class=\"gk-math\" data-tex=\"y\">y</span> 轴、<span class=\"gk-math\" data-tex=\"z\">z</span> 轴建立空间直角坐标系. 因为 <span class=\"gk-math\" data-tex=\"ABB_1A_1\">ABB_1A_1</span> 为 <span class=\"gk-math\" data-tex=\"AA_1=AB\">AA_1=AB</span> 的矩形，故为正方形，所以 <span class=\"gk-math\" data-tex=\"A_1B=\\sqrt2AB\">A_1B=\\sqrt2AB</span>，<span class=\"gk-math\" data-tex=\"AE=\\frac12A_1B=\\frac{\\sqrt2}{2}AB\">AE=\\frac12A_1B=\\frac{\\sqrt2}{2}AB</span>. 由 <span class=\"gk-math\" data-tex=\"AE=\\sqrt2\">AE=\\sqrt2</span> 得 <span class=\"gk-math\" data-tex=\"AB=2\">AB=2</span>，所以 <span class=\"gk-math\" data-tex=\"AA_1=2\">AA_1=2</span>，<span class=\"gk-math\" data-tex=\"A_1B=2\\sqrt2\">A_1B=2\\sqrt2</span>. 又 <span class=\"gk-math\" data-tex=\"BC\\perp\">BC\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"ABB_1A_1\">ABB_1A_1</span>，所以 <span class=\"gk-math\" data-tex=\"BC\\perp A_1B\">BC\\perp A_1B</span>，故 <span class=\"gk-math\" data-tex=\"S_{\\triangle A_1BC}=\\frac12A_1B\\cdot BC=2\\sqrt2\">S_{\\triangle A_1BC}=\\frac12A_1B\\cdot BC=2\\sqrt2</span>，解得 <span class=\"gk-math\" data-tex=\"BC=2\">BC=2</span>. 则 <span class=\"gk-math\" data-tex=\"A(0,2,0)\">A(0,2,0)</span>，<span class=\"gk-math\" data-tex=\"A_1(0,2,2)\">A_1(0,2,2)</span>，<span class=\"gk-math\" data-tex=\"B(0,0,0)\">B(0,0,0)</span>，<span class=\"gk-math\" data-tex=\"C(2,0,0)\">C(2,0,0)</span>，所以 <span class=\"gk-math\" data-tex=\"A_1C\">A_1C</span> 的中点 <span class=\"gk-math\" data-tex=\"D(1,1,1)\">D(1,1,1)</span>. 则 <span class=\"gk-math\" data-tex=\"\\overrightarrow{BD}=(1,1,1)\">\\overrightarrow{BD}=(1,1,1)</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{BA}=(0,2,0)\">\\overrightarrow{BA}=(0,2,0)</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{BC}=(2,0,0)\">\\overrightarrow{BC}=(2,0,0)</span>. 设平面 <span class=\"gk-math\" data-tex=\"ABD\">ABD</span> 的一个法向量 <span class=\"gk-math\" data-tex=\"\\bs m=(x,y,z)\">\\bs m=(x,y,z)</span>，则由 <span class=\"gk-math\" data-tex=\"\\bs m\\cdot \\overrightarrow{BD}=x+y+z=0\">\\bs m\\cdot \\overrightarrow{BD}=x+y+z=0</span> 和 <span class=\"gk-math\" data-tex=\"\\bs m\\cdot \\overrightarrow{BA}=2y=0\">\\bs m\\cdot \\overrightarrow{BA}=2y=0</span> 可取 <span class=\"gk-math\" data-tex=\"\\bs m=(1,0,-1)\">\\bs m=(1,0,-1)</span>. 设平面 <span class=\"gk-math\" data-tex=\"BDC\">BDC</span> 的一个法向量 <span class=\"gk-math\" data-tex=\"\\bs n=(a,b,c)\">\\bs n=(a,b,c)</span>，则由 <span class=\"gk-math\" data-tex=\"\\bs n\\cdot \\overrightarrow{BD}=a+b+c=0\">\\bs n\\cdot \\overrightarrow{BD}=a+b+c=0</span> 和 <span class=\"gk-math\" data-tex=\"\\bs n\\cdot \\overrightarrow{BC}=2a=0\">\\bs n\\cdot \\overrightarrow{BC}=2a=0</span> 可取 <span class=\"gk-math\" data-tex=\"\\bs n=(0,1,-1)\">\\bs n=(0,1,-1)</span>. 则 <span class=\"gk-math\" data-tex=\"\\cos\\langle\\bs m,\\bs n\\rangle=\\frac{\\bs m\\cdot \\bs n}{|\\bs m||\\bs n|}=\\frac{1}{\\sqrt2\\times \\sqrt2}=\\frac12\">\\cos\\langle\\bs m,\\bs n\\rangle=\\frac{\\bs m\\cdot \\bs n}{|\\bs m||\\bs n|}=\\frac{1}{\\sqrt2\\times \\sqrt2}=\\frac12</span>，所以二面角 <span class=\"gk-math\" data-tex=\"A-BD-C\">A-BD-C</span> 的正弦值为 <span class=\"gk-math\" data-tex=\"\\sqrt{1-\\left(\\frac12\\right)^2}=\\frac{\\sqrt3}{2}\">\\sqrt{1-\\left(\\frac12\\right)^2}=\\frac{\\sqrt3}{2}</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q20","paperId":"2022-new_gaokao_paper_1","number":20,"type":"written","score":12,"lessonIds":["e3-8.3","e3-7.1"],"difficulty":"挑战","hint":"第一问按列联表代入 K²；第二问先用条件概率定义把各项都改写成联合概率的商。","legacy":false,"legacyReason":"","searchText":"一医疗团队为研究某地的一种地方性疾病与当地居民的卫生习惯（卫生习惯分为良好和不够良好两类）的关系，在已患该疾病的病例中随机调查了 100 例（称为病例组），同时在未患该疾病的人群中随机调查了 100 人（称为对照组），得到如下数据： 不够良好 良好 病例组 40 60 对照组 10 90 能否有 99\\% 的把握认为患该疾病群体与未患该疾病群体的卫生习惯有差异？ 从该地的人群中任选一人， A 表示事件“选到的人卫生习惯不够良好”， B 表示事件“选到的人患有该疾病”. \\frac{P(B\\mid A)}{P(\\overline B\\mid A)} 与 \\frac{P(B\\mid \\overline A)}{P(\\overline B\\mid \\overline A)} 的比值是卫生习惯不够良好对患该疾病风险程度的一项度量指标，记该指标为 R . 证明： R=\\frac{P(B\\mid A)}{P(\\overline B\\mid A)}\\div \\frac{P(B\\mid \\overline A)}{P(\\overline B\\mid \\overline A)}=\\frac{P(A\\mid B)}{P(\\overline A\\mid B)}\\cdot \\frac{P(\\overline A\\mid \\overline B)}{P(A\\mid \\overline B)}; 利用该调查数据，给出 P(A\\mid B) ， P(A\\mid \\overline B) 的估计值，并利用（1）的结果给出 R 的估计值. 附： K^2=\\frac{n(ad-bc)^2}{(a+b)(c+d)(a+c)(b+d)} ， P(K^2\\ge k) 0.050 0.010 0.001 k 3.841 6.635 10.828 ","questionHtml":"一医疗团队为研究某地的一种地方性疾病与当地居民的卫生习惯（卫生习惯分为良好和不够良好两类）的关系，在已患该疾病的病例中随机调查了 <span class=\"gk-math\" data-tex=\"100\">100</span> 例（称为病例组），同时在未患该疾病的人群中随机调查了 <span class=\"gk-math\" data-tex=\"100\">100</span> 人（称为对照组），得到如下数据：<br><br><div class=\"gk-center\"><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td></td><td>不够良好</td><td>良好</td></tr><tr><td>病例组</td><td>40</td><td>60</td></tr><tr><td>对照组</td><td>10</td><td>90</td></tr></table></div></div><br><br><ol class=\"gk-subparts\"><li>能否有 <span class=\"gk-math\" data-tex=\"99\\%\">99\\%</span> 的把握认为患该疾病群体与未患该疾病群体的卫生习惯有差异？</li><li>从该地的人群中任选一人，<span class=\"gk-math\" data-tex=\"A\">A</span> 表示事件“选到的人卫生习惯不够良好”，<span class=\"gk-math\" data-tex=\"B\">B</span> 表示事件“选到的人患有该疾病”. <span class=\"gk-math\" data-tex=\"\\frac{P(B\\mid A)}{P(\\overline B\\mid A)}\">\\frac{P(B\\mid A)}{P(\\overline B\\mid A)}</span> 与 <span class=\"gk-math\" data-tex=\"\\frac{P(B\\mid \\overline A)}{P(\\overline B\\mid \\overline A)}\">\\frac{P(B\\mid \\overline A)}{P(\\overline B\\mid \\overline A)}</span> 的比值是卫生习惯不够良好对患该疾病风险程度的一项度量指标，记该指标为 <span class=\"gk-math\" data-tex=\"R\">R</span>.<br><br><ol class=\"gk-subparts\"><li>证明：<span class=\"gk-math\" data-tex=\"R=\\frac{P(B\\mid A)}{P(\\overline B\\mid A)}\\div \\frac{P(B\\mid \\overline A)}{P(\\overline B\\mid \\overline A)}=\\frac{P(A\\mid B)}{P(\\overline A\\mid B)}\\cdot \\frac{P(\\overline A\\mid \\overline B)}{P(A\\mid \\overline B)};\">R=\\frac{P(B\\mid A)}{P(\\overline B\\mid A)}\\div \\frac{P(B\\mid \\overline A)}{P(\\overline B\\mid \\overline A)}=\\frac{P(A\\mid B)}{P(\\overline A\\mid B)}\\cdot \\frac{P(\\overline A\\mid \\overline B)}{P(A\\mid \\overline B)};</span></li><li>利用该调查数据，给出 <span class=\"gk-math\" data-tex=\"P(A\\mid B)\">P(A\\mid B)</span>，<span class=\"gk-math\" data-tex=\"P(A\\mid \\overline B)\">P(A\\mid \\overline B)</span> 的估计值，并利用（1）的结果给出 <span class=\"gk-math\" data-tex=\"R\">R</span> 的估计值.</li></ol><br><br>附：<span class=\"gk-math\" data-tex=\"K^2=\\frac{n(ad-bc)^2}{(a+b)(c+d)(a+c)(b+d)}\">K^2=\\frac{n(ad-bc)^2}{(a+b)(c+d)(a+c)(b+d)}</span>，<br><br><div class=\"gk-center\"><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td><span class=\"gk-math\" data-tex=\"P(K^2\\ge k)\">P(K^2\\ge k)</span></td><td>0.050</td><td>0.010</td><td>0.001</td></tr><tr><td><span class=\"gk-math\" data-tex=\"k\">k</span></td><td>3.841</td><td>6.635</td><td>10.828</td></tr></table></div></div></li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>补全列联表：  <div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td></td><td>不够良好</td><td>良好</td><td>合计</td></tr><tr><td>病例组</td><td>40</td><td>60</td><td>100</td></tr><tr><td>对照组</td><td>10</td><td>90</td><td>100</td></tr><tr><td>合计</td><td>50</td><td>150</td><td>200</td></tr></table></div> <br> 因为 <span class=\"gk-math\" data-tex=\"40\\times 90-10\\times 60=3000\">40\\times 90-10\\times 60=3000</span>，所以 <span class=\"gk-math\" data-tex=\"K^2=\\frac{200(40\\times 90-10\\times 60)^2}{100\\times 100\\times 50\\times 150}=24\">K^2=\\frac{200(40\\times 90-10\\times 60)^2}{100\\times 100\\times 50\\times 150}=24</span>. 因为 <span class=\"gk-math\" data-tex=\"24&gt;6.635\">24&gt;6.635</span>，所以有 <span class=\"gk-math\" data-tex=\"99\\%\">99\\%</span> 的把握认为两类人群的卫生习惯有差异.</li><li><ol class=\"gk-subparts\"><li>证明： <span class=\"gk-math\" data-tex=\"R=\\frac{P(B\\mid A)}{P(\\overline B\\mid A)}\\div \\frac{P(B\\mid \\overline A)}{P(\\overline B\\mid \\overline A)}=\\frac{\\frac{P(AB)}{P(A)}}{\\frac{P(A\\overline B)}{P(A)}}\\div \\frac{\\frac{P(\\overline AB)}{P(\\overline A)}}{\\frac{P(\\overline A\\overline B)}{P(\\overline A)}}=\\frac{P(AB)}{P(A\\overline B)}\\cdot \\frac{P(\\overline A\\overline B)}{P(\\overline AB)}=\\frac{P(A\\mid B)}{P(\\overline A\\mid B)}\\cdot \\frac{P(\\overline A\\mid \\overline B)}{P(A\\mid \\overline B)}\">R=\\frac{P(B\\mid A)}{P(\\overline B\\mid A)}\\div \\frac{P(B\\mid \\overline A)}{P(\\overline B\\mid \\overline A)}=\\frac{\\frac{P(AB)}{P(A)}}{\\frac{P(A\\overline B)}{P(A)}}\\div \\frac{\\frac{P(\\overline AB)}{P(\\overline A)}}{\\frac{P(\\overline A\\overline B)}{P(\\overline A)}}=\\frac{P(AB)}{P(A\\overline B)}\\cdot \\frac{P(\\overline A\\overline B)}{P(\\overline AB)}=\\frac{P(A\\mid B)}{P(\\overline A\\mid B)}\\cdot \\frac{P(\\overline A\\mid \\overline B)}{P(A\\mid \\overline B)}</span>.</li><li>由调查数据估计 <span class=\"gk-math\" data-tex=\"P(A\\mid B)=\\frac{40}{100}=\\frac25\">P(A\\mid B)=\\frac{40}{100}=\\frac25</span>，<span class=\"gk-math\" data-tex=\"P(A\\mid \\overline B)=\\frac{10}{100}=\\frac1{10}\">P(A\\mid \\overline B)=\\frac{10}{100}=\\frac1{10}</span>. 于是 <span class=\"gk-math\" data-tex=\"P(\\overline A\\mid B)=\\frac35\">P(\\overline A\\mid B)=\\frac35</span>，<span class=\"gk-math\" data-tex=\"P(\\overline A\\mid \\overline B)=\\frac9{10}\">P(\\overline A\\mid \\overline B)=\\frac9{10}</span>. 代入（1）得 <span class=\"gk-math\" data-tex=\"R=\\frac{\\frac25}{\\frac35}\\cdot \\frac{\\frac9{10}}{\\frac1{10}}=6\">R=\\frac{\\frac25}{\\frac35}\\cdot \\frac{\\frac9{10}}{\\frac1{10}}=6</span>.</li></ol></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q21","paperId":"2022-new_gaokao_paper_1","number":21,"type":"written","score":12,"lessonIds":["e1-3.2","e1-2.1"],"difficulty":"挑战","hint":"先将 A=(2,1) 代入双曲线方程求 a²，再用 AP、AQ 斜率互为相反数设两条直线。","legacy":false,"legacyReason":"","searchText":"已知点 A(2,1) 在双曲线 C:\\ \\frac{x^2}{a^2}-\\frac{y^2}{a^2-1}=1 （ a>1 ） 上，直线 l 交 C 于 P ， Q 两点，直线 AP ， AQ 的斜率之和为 0 . 求 l 的斜率； 若 \\tan \\angle PAQ=2\\sqrt2 ，求 \\triangle PAQ 的面积. ","questionHtml":"已知点 <span class=\"gk-math\" data-tex=\"A(2,1)\">A(2,1)</span> 在双曲线 <span class=\"gk-math\" data-tex=\"C:\\ \\frac{x^2}{a^2}-\\frac{y^2}{a^2-1}=1\">C:\\ \\frac{x^2}{a^2}-\\frac{y^2}{a^2-1}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;1\">a&gt;1</span>） 上，直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 交 <span class=\"gk-math\" data-tex=\"C\">C</span> 于 <span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span> 两点，直线 <span class=\"gk-math\" data-tex=\"AP\">AP</span>，<span class=\"gk-math\" data-tex=\"AQ\">AQ</span> 的斜率之和为 <span class=\"gk-math\" data-tex=\"0\">0</span>.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"l\">l</span> 的斜率；</li><li>若 <span class=\"gk-math\" data-tex=\"\\tan \\angle PAQ=2\\sqrt2\">\\tan \\angle PAQ=2\\sqrt2</span>，求 <span class=\"gk-math\" data-tex=\"\\triangle PAQ\">\\triangle PAQ</span> 的面积.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>因为 <span class=\"gk-math\" data-tex=\"A(2,1)\\in C\">A(2,1)\\in C</span>，所以 <span class=\"gk-math\" data-tex=\"\\frac{4}{a^2}-\\frac{1}{a^2-1}=1\">\\frac{4}{a^2}-\\frac{1}{a^2-1}=1</span>，整理得 <span class=\"gk-math\" data-tex=\"a^4-4a^2+4=0\">a^4-4a^2+4=0</span>，即 <span class=\"gk-math\" data-tex=\"\\left(a^2-2\\right)^2=0\">\\left(a^2-2\\right)^2=0</span>，解得 <span class=\"gk-math\" data-tex=\"a^2=2\">a^2=2</span>. 故双曲线方程为 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{2}-y^2=1\">\\frac{x^2}{2}-y^2=1</span>. 若直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 的斜率不存在，则可设 <span class=\"gk-math\" data-tex=\"l:x=t\">l:x=t</span>. 当 <span class=\"gk-math\" data-tex=\"t=2\">t=2</span> 时，直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 经过点 <span class=\"gk-math\" data-tex=\"A\">A</span>，此时直线 <span class=\"gk-math\" data-tex=\"AP\">AP</span> 或 <span class=\"gk-math\" data-tex=\"AQ\">AQ</span> 的斜率不存在，与题意不符. 当 <span class=\"gk-math\" data-tex=\"t\\ne 2\">t\\ne 2</span> 时，直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 与双曲线 <span class=\"gk-math\" data-tex=\"C\">C</span> 的交点可设为 <span class=\"gk-math\" data-tex=\"P(t,y_1)\">P(t,y_1)</span>，<span class=\"gk-math\" data-tex=\"Q(t,y_2)\">Q(t,y_2)</span>，由 <span class=\"gk-math\" data-tex=\"\\frac{t^2}{2}-y^2=1\">\\frac{t^2}{2}-y^2=1</span> ，所以 <span class=\"gk-math\" data-tex=\"y_1+y_2=0\">y_1+y_2=0</span>，从而 <span class=\"gk-math\" data-tex=\"k_{AP}+k_{AQ}=\\frac{y_1-1}{t-2}+\\frac{y_2-1}{t-2}=\\frac{y_1+y_2-2}{t-2}=-\\frac{2}{t-2}\\ne 0\">k_{AP}+k_{AQ}=\\frac{y_1-1}{t-2}+\\frac{y_2-1}{t-2}=\\frac{y_1+y_2-2}{t-2}=-\\frac{2}{t-2}\\ne 0</span>，这与已知条件矛盾. 所以直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 的斜率存在，设 <span class=\"gk-math\" data-tex=\"l:y=kx+m\">l:y=kx+m</span>，<span class=\"gk-math\" data-tex=\"P(x_1,y_1)\">P(x_1,y_1)</span>，<span class=\"gk-math\" data-tex=\"Q(x_2,y_2)\">Q(x_2,y_2)</span>. 联立 <span class=\"gk-math\" data-tex=\"y=kx+m\">y=kx+m</span> 和 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{2}-y^2=1\">\\frac{x^2}{2}-y^2=1</span>，得到 <span class=\"gk-math\" data-tex=\"\\left(1-2k^2\\right)x^2-4mkx-2m^2-2=0\">\\left(1-2k^2\\right)x^2-4mkx-2m^2-2=0</span>. 因为是一元二次方程，所以 <span class=\"gk-math\" data-tex=\"k\\ne \\pm \\frac{\\sqrt2}{2}\">k\\ne \\pm \\frac{\\sqrt2}{2}</span>，且判别式 <span class=\"gk-math\" data-tex=\"\\Delta=16m^2k^2+4\\left(1-2k^2\\right)\\left(2m^2+2\\right)=8\\left(m^2+1-2k^2\\right)&gt;0\">\\Delta=16m^2k^2+4\\left(1-2k^2\\right)\\left(2m^2+2\\right)=8\\left(m^2+1-2k^2\\right)&gt;0</span>，即 <span class=\"gk-math\" data-tex=\"m^2+1-2k^2&gt;0\">m^2+1-2k^2&gt;0</span>. 由韦达定理，<span class=\"gk-math\" data-tex=\"x_1+x_2=\\frac{4mk}{1-2k^2}=-\\frac{4mk}{2k^2-1}\">x_1+x_2=\\frac{4mk}{1-2k^2}=-\\frac{4mk}{2k^2-1}</span>，<span class=\"gk-math\" data-tex=\"x_1x_2=\\frac{-2m^2-2}{1-2k^2}=\\frac{2m^2+2}{2k^2-1}\">x_1x_2=\\frac{-2m^2-2}{1-2k^2}=\\frac{2m^2+2}{2k^2-1}</span>. 因为直线 <span class=\"gk-math\" data-tex=\"AP\">AP</span>，<span class=\"gk-math\" data-tex=\"AQ\">AQ</span> 斜率存在，所以 <span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span> 均不为 <span class=\"gk-math\" data-tex=\"A\">A</span>，故 <span class=\"gk-math\" data-tex=\"l\">l</span> 不过点 <span class=\"gk-math\" data-tex=\"A\">A</span>. 由 <span class=\"gk-math\" data-tex=\"k_{AP}+k_{AQ}=0\">k_{AP}+k_{AQ}=0</span> 得 <span class=\"gk-math\" data-tex=\"\\frac{y_1-1}{x_1-2}+\\frac{y_2-1}{x_2-2}=0\">\\frac{y_1-1}{x_1-2}+\\frac{y_2-1}{x_2-2}=0</span>，即 <span class=\"gk-math\" data-tex=\"\\left(x_1-2\\right)\\left(kx_2+m-1\\right)+\\left(x_2-2\\right)\\left(kx_1+m-1\\right)=0\">\\left(x_1-2\\right)\\left(kx_2+m-1\\right)+\\left(x_2-2\\right)\\left(kx_1+m-1\\right)=0</span>，即 <span class=\"gk-math\" data-tex=\"2kx_1x_2+(m-1-2k)\\left(x_1+x_2\\right)-4(m-1)=0\">2kx_1x_2+(m-1-2k)\\left(x_1+x_2\\right)-4(m-1)=0</span>. 代入韦达结果，通分后分子为 <span class=\"gk-math\" data-tex=\"2k\\left(2m^2+2\\right)+(m-1-2k)(-4mk)-4(m-1)\\left(2k^2-1\\right)\">2k\\left(2m^2+2\\right)+(m-1-2k)(-4mk)-4(m-1)\\left(2k^2-1\\right)</span>. 展开后 <span class=\"gk-math\" data-tex=\"4km^2\">4km^2</span> 与 <span class=\"gk-math\" data-tex=\"-4m^2k\">-4m^2k</span> 相消，<span class=\"gk-math\" data-tex=\"8mk^2\">8mk^2</span> 与 <span class=\"gk-math\" data-tex=\"-8mk^2\">-8mk^2</span> 相消，余下 <span class=\"gk-math\" data-tex=\"4(k+mk+m+2k^2-1)=4(k+1)(m+2k-1)\">4(k+mk+m+2k^2-1)=4(k+1)(m+2k-1)</span>，所以化简得 <span class=\"gk-math\" data-tex=\"(k+1)(m+2k-1)=0\">(k+1)(m+2k-1)=0</span>. 若 <span class=\"gk-math\" data-tex=\"m=1-2k\">m=1-2k</span>，则直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 过点 <span class=\"gk-math\" data-tex=\"A\">A</span>，与题意不符，故 <span class=\"gk-math\" data-tex=\"k=-1\">k=-1</span>.</li><li>由（1）知 <span class=\"gk-math\" data-tex=\"k=-1\">k=-1</span>，则 <span class=\"gk-math\" data-tex=\"x_1x_2=2m^2+2&gt;0\">x_1x_2=2m^2+2&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"x_1\">x_1</span>，<span class=\"gk-math\" data-tex=\"x_2\">x_2</span> 同号. 不妨设直线 <span class=\"gk-math\" data-tex=\"PA\">PA</span>，<span class=\"gk-math\" data-tex=\"AQ\">AQ</span> 的倾斜角为 <span class=\"gk-math\" data-tex=\"\\alpha\">\\alpha</span>，<span class=\"gk-math\" data-tex=\"\\beta\">\\beta</span>（<span class=\"gk-math\" data-tex=\"\\alpha&lt;\\frac{\\pi}{2}&lt;\\beta\">\\alpha&lt;\\frac{\\pi}{2}&lt;\\beta</span>），因为 <span class=\"gk-math\" data-tex=\"k_{AP}+k_{AQ}=0\">k_{AP}+k_{AQ}=0</span>，所以 <span class=\"gk-math\" data-tex=\"\\alpha+\\beta=\\pi\">\\alpha+\\beta=\\pi</span>. 当 <span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span> 均在双曲线左支时，<span class=\"gk-math\" data-tex=\"\\angle PAQ=2\\alpha\">\\angle PAQ=2\\alpha</span>，所以 <span class=\"gk-math\" data-tex=\"\\tan 2\\alpha=2\\sqrt2\">\\tan 2\\alpha=2\\sqrt2</span>，即 <span class=\"gk-math\" data-tex=\"\\sqrt2\\tan^2\\alpha+\\tan\\alpha-\\sqrt2=0\">\\sqrt2\\tan^2\\alpha+\\tan\\alpha-\\sqrt2=0</span>，分解得 <span class=\"gk-math\" data-tex=\"\\left(\\sqrt2\\tan\\alpha-1\\right)(\\tan\\alpha+\\sqrt2)=0\">\\left(\\sqrt2\\tan\\alpha-1\\right)(\\tan\\alpha+\\sqrt2)=0</span>，解得 <span class=\"gk-math\" data-tex=\"\\tan\\alpha=\\frac{\\sqrt2}{2}\">\\tan\\alpha=\\frac{\\sqrt2}{2}</span>（负值舍去）. 此时 <span class=\"gk-math\" data-tex=\"PA\">PA</span> 的斜率等于渐近线 <span class=\"gk-math\" data-tex=\"y=\\frac{\\sqrt2}{2}x\">y=\\frac{\\sqrt2}{2}x</span> 的斜率，与双曲线左支无交点，舍去. 当 <span class=\"gk-math\" data-tex=\"P\">P</span>，<span class=\"gk-math\" data-tex=\"Q\">Q</span> 均在双曲线右支时，<span class=\"gk-math\" data-tex=\"\\tan\\angle PAQ=2\\sqrt2\">\\tan\\angle PAQ=2\\sqrt2</span>，所以 <span class=\"gk-math\" data-tex=\"\\tan(\\beta-\\alpha)=2\\sqrt2\">\\tan(\\beta-\\alpha)=2\\sqrt2</span>，即 <span class=\"gk-math\" data-tex=\"\\tan 2\\alpha=-2\\sqrt2\">\\tan 2\\alpha=-2\\sqrt2</span>，也就是 <span class=\"gk-math\" data-tex=\"\\sqrt2\\tan^2\\alpha-\\tan\\alpha-\\sqrt2=0\">\\sqrt2\\tan^2\\alpha-\\tan\\alpha-\\sqrt2=0</span>，分解得 <span class=\"gk-math\" data-tex=\"\\left(\\sqrt2\\tan\\alpha+1\\right)(\\tan\\alpha-\\sqrt2)=0\">\\left(\\sqrt2\\tan\\alpha+1\\right)(\\tan\\alpha-\\sqrt2)=0</span>，解得 <span class=\"gk-math\" data-tex=\"\\tan\\alpha=\\sqrt2\">\\tan\\alpha=\\sqrt2</span>（负值舍去）. 于是 <span class=\"gk-math\" data-tex=\"PA:y=\\sqrt2(x-2)+1\">PA:y=\\sqrt2(x-2)+1</span>，<span class=\"gk-math\" data-tex=\"AQ:y=-\\sqrt2(x-2)+1\">AQ:y=-\\sqrt2(x-2)+1</span>. 联立 <span class=\"gk-math\" data-tex=\"y=\\sqrt2(x-2)+1\">y=\\sqrt2(x-2)+1</span> 和 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{2}-y^2=1\">\\frac{x^2}{2}-y^2=1</span>，得到 <span class=\"gk-math\" data-tex=\"\\frac32x^2+2\\left(\\sqrt2-4\\right)x+10-4\\sqrt2=0\">\\frac32x^2+2\\left(\\sqrt2-4\\right)x+10-4\\sqrt2=0</span>. 因为方程有一个根为 <span class=\"gk-math\" data-tex=\"2\">2</span>，由韦达定理两根之和为 <span class=\"gk-math\" data-tex=\"\\frac{16-4\\sqrt2}{3}\">\\frac{16-4\\sqrt2}{3}</span>，所以另一根为 <span class=\"gk-math\" data-tex=\"\\frac{10-4\\sqrt2}{3}\">\\frac{10-4\\sqrt2}{3}</span>，得 <span class=\"gk-math\" data-tex=\"P\\left(\\frac{10-4\\sqrt2}{3},\\frac{4\\sqrt2-5}{3}\\right)\">P\\left(\\frac{10-4\\sqrt2}{3},\\frac{4\\sqrt2-5}{3}\\right)</span>. 联立 <span class=\"gk-math\" data-tex=\"y=-\\sqrt2(x-2)+1\">y=-\\sqrt2(x-2)+1</span> 和 <span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{2}-y^2=1\">\\dfrac{x^2}{2}-y^2=1</span>，得 <span class=\"gk-math\" data-tex=\"\\frac32x^2-2\\left(\\sqrt2+4\\right)x+10+4\\sqrt2=0\">\\frac32x^2-2\\left(\\sqrt2+4\\right)x+10+4\\sqrt2=0</span>. 该方程同样以 <span class=\"gk-math\" data-tex=\"2\">2</span> 为一根，由韦达定理两根之和为 <span class=\"gk-math\" data-tex=\"\\frac{16+4\\sqrt2}{3}\">\\frac{16+4\\sqrt2}{3}</span>，所以另一根为 <span class=\"gk-math\" data-tex=\"\\frac{10+4\\sqrt2}{3}\">\\frac{10+4\\sqrt2}{3}</span>，得 <span class=\"gk-math\" data-tex=\"Q\\left(\\frac{10+4\\sqrt2}{3},\\frac{-4\\sqrt2-5}{3}\\right)\">Q\\left(\\frac{10+4\\sqrt2}{3},\\frac{-4\\sqrt2-5}{3}\\right)</span>. 所以 <span class=\"gk-math\" data-tex=\"PQ:x+y-\\frac53=0\">PQ:x+y-\\frac53=0</span>，<span class=\"gk-math\" data-tex=\"|PQ|=\\frac{16}{3}\">|PQ|=\\frac{16}{3}</span>. 点 <span class=\"gk-math\" data-tex=\"A\">A</span> 到直线 <span class=\"gk-math\" data-tex=\"PQ\">PQ</span> 的距离为 <span class=\"gk-math\" data-tex=\"d=\\frac{\\left|2+1-\\frac53\\right|}{\\sqrt2}=\\frac{2\\sqrt2}{3}\">d=\\frac{\\left|2+1-\\frac53\\right|}{\\sqrt2}=\\frac{2\\sqrt2}{3}</span>. 故 <span class=\"gk-math\" data-tex=\"S_{\\triangle PAQ}=\\frac12\\cdot \\frac{16}{3}\\cdot \\frac{2\\sqrt2}{3}=\\frac{16\\sqrt2}{9}\">S_{\\triangle PAQ}=\\frac12\\cdot \\frac{16}{3}\\cdot \\frac{2\\sqrt2}{3}=\\frac{16\\sqrt2}{9}</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-new_gaokao_paper_1-q22","paperId":"2022-new_gaokao_paper_1","number":22,"type":"written","score":12,"lessonIds":["e2-5.3","4.2","4.4"],"difficulty":"挑战","hint":"两个函数有最小值先要求 a>0，再分别令导数为零，比较两处最小值。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x)=\\e^x-ax ， g(x)=ax-\\ln x 有相同的最小值. 求 a ； 证明：存在直线 y=b ，其与两条曲线 y=f(x) 和 y=g(x) 共有三个不同的交点，并且从左到右的三个交点的横坐标成等差数列. ","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)=\\e^x-ax\">f(x)=\\e^x-ax</span>，<span class=\"gk-math\" data-tex=\"g(x)=ax-\\ln x\">g(x)=ax-\\ln x</span> 有相同的最小值.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"a\">a</span>；</li><li>证明：存在直线 <span class=\"gk-math\" data-tex=\"y=b\">y=b</span>，其与两条曲线 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 和 <span class=\"gk-math\" data-tex=\"y=g(x)\">y=g(x)</span> 共有三个不同的交点，并且从左到右的三个交点的横坐标成等差数列.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>对 <span class=\"gk-math\" data-tex=\"f(x)=\\e^x-ax\">f(x)=\\e^x-ax</span>（<span class=\"gk-math\" data-tex=\"x\\in\\R\">x\\in\\R</span>）有 <span class=\"gk-math\" data-tex=\"f^{\\prime}(x)=\\e^x-a\">f^{\\prime}(x)=\\e^x-a</span>. 当 <span class=\"gk-math\" data-tex=\"a\\le 0\">a\\le 0</span> 时，<span class=\"gk-math\" data-tex=\"f^{\\prime}(x)&gt;0\">f^{\\prime}(x)&gt;0</span> 恒成立，所以 <span class=\"gk-math\" data-tex=\"f\">f</span> 在 <span class=\"gk-math\" data-tex=\"\\R\">\\R</span> 上单调递增，无最小值，故 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>. 此时由 <span class=\"gk-math\" data-tex=\"f^{\\prime}(x)=0\">f^{\\prime}(x)=0</span> 得 <span class=\"gk-math\" data-tex=\"x=\\ln a\">x=\\ln a</span>，当 <span class=\"gk-math\" data-tex=\"x&lt;\\ln a\">x&lt;\\ln a</span> 时 <span class=\"gk-math\" data-tex=\"f^{\\prime}(x)&lt;0\">f^{\\prime}(x)&lt;0</span>，当 <span class=\"gk-math\" data-tex=\"x&gt;\\ln a\">x&gt;\\ln a</span> 时 <span class=\"gk-math\" data-tex=\"f^{\\prime}(x)&gt;0\">f^{\\prime}(x)&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"f\">f</span> 的最小值为 <span class=\"gk-math\" data-tex=\"f(\\ln a)=a-a\\ln a\">f(\\ln a)=a-a\\ln a</span>. 对 <span class=\"gk-math\" data-tex=\"g(x)=ax-\\ln x\">g(x)=ax-\\ln x</span>（<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>）有 <span class=\"gk-math\" data-tex=\"g^{\\prime}(x)=a-\\frac1x\">g^{\\prime}(x)=a-\\frac1x</span>. 因为 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，当 <span class=\"gk-math\" data-tex=\"0&lt;x&lt;\\frac1a\">0&lt;x&lt;\\frac1a</span> 时 <span class=\"gk-math\" data-tex=\"g^{\\prime}(x)&lt;0\">g^{\\prime}(x)&lt;0</span>，故 <span class=\"gk-math\" data-tex=\"g\">g</span> 在 <span class=\"gk-math\" data-tex=\"\\left(0,\\frac1a\\right)\">\\left(0,\\frac1a\\right)</span> 上为减函数. 当 <span class=\"gk-math\" data-tex=\"x&gt;\\frac1a\">x&gt;\\frac1a</span> 时 <span class=\"gk-math\" data-tex=\"g^{\\prime}(x)&gt;0\">g^{\\prime}(x)&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"g\">g</span> 在 <span class=\"gk-math\" data-tex=\"\\left(\\frac1a,+\\infty\\right)\">\\left(\\frac1a,+\\infty\\right)</span> 上为增函数. 故 <span class=\"gk-math\" data-tex=\"g\">g</span> 的最小值为 <span class=\"gk-math\" data-tex=\"g\\left(\\frac1a\\right)=1-\\ln\\frac1a=1+\\ln a\">g\\left(\\frac1a\\right)=1-\\ln\\frac1a=1+\\ln a</span>. 因为 <span class=\"gk-math\" data-tex=\"f\">f</span> 和 <span class=\"gk-math\" data-tex=\"g\">g</span> 有相同的最小值，故 <span class=\"gk-math\" data-tex=\"a-a\\ln a=1+\\ln a\">a-a\\ln a=1+\\ln a</span>，整理为 <span class=\"gk-math\" data-tex=\"a-1=(a+1)\\ln a\">a-1=(a+1)\\ln a</span>，即 <span class=\"gk-math\" data-tex=\"\\frac{a-1}{a+1}=\\ln a\">\\frac{a-1}{a+1}=\\ln a</span>. 设 <span class=\"gk-math\" data-tex=\"\\phi(a)=\\frac{a-1}{a+1}-\\ln a\">\\phi(a)=\\frac{a-1}{a+1}-\\ln a</span>（<span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>），则 <span class=\"gk-math\" data-tex=\"\\phi^{\\prime}(a)=\\frac{2}{(1+a)^2}-\\frac1a=-\\frac{a^2+1}{a(1+a)^2}&lt;0\">\\phi^{\\prime}(a)=\\frac{2}{(1+a)^2}-\\frac1a=-\\frac{a^2+1}{a(1+a)^2}&lt;0</span>. 故 <span class=\"gk-math\" data-tex=\"\\phi\">\\phi</span> 单调递减，而 <span class=\"gk-math\" data-tex=\"\\phi(1)=0\">\\phi(1)=0</span>，所以唯一解为 <span class=\"gk-math\" data-tex=\"a=1\">a=1</span>.</li><li>由（1）知 <span class=\"gk-math\" data-tex=\"f(x)=\\e^x-x\">f(x)=\\e^x-x</span>，<span class=\"gk-math\" data-tex=\"g(x)=x-\\ln x\">g(x)=x-\\ln x</span>，最小值均为 <span class=\"gk-math\" data-tex=\"1\">1</span>. 当 <span class=\"gk-math\" data-tex=\"b&gt;1\">b&gt;1</span> 时，设 <span class=\"gk-math\" data-tex=\"S(x)=\\e^x-x-b\">S(x)=\\e^x-x-b</span>，则 <span class=\"gk-math\" data-tex=\"S^{\\prime}(x)=\\e^x-1\">S^{\\prime}(x)=\\e^x-1</span>. 当 <span class=\"gk-math\" data-tex=\"x&lt;0\">x&lt;0</span> 时 <span class=\"gk-math\" data-tex=\"S^{\\prime}(x)&lt;0\">S^{\\prime}(x)&lt;0</span>，当 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span> 时 <span class=\"gk-math\" data-tex=\"S^{\\prime}(x)&gt;0\">S^{\\prime}(x)&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"S\">S</span> 在 <span class=\"gk-math\" data-tex=\"(-\\infty,0)\">(-\\infty,0)</span> 上为减函数，在 <span class=\"gk-math\" data-tex=\"(0,+\\infty)\">(0,+\\infty)</span> 上为增函数，所以 <span class=\"gk-math\" data-tex=\"S(x)_{\\min}=S(0)=1-b&lt;0\">S(x)_{\\min}=S(0)=1-b&lt;0</span>. 而 <span class=\"gk-math\" data-tex=\"S(-b)=\\e^{-b}&gt;0\">S(-b)=\\e^{-b}&gt;0</span>，<span class=\"gk-math\" data-tex=\"S(b)=\\e^b-2b\">S(b)=\\e^b-2b</span>. 设 <span class=\"gk-math\" data-tex=\"u(b)=\\e^b-2b\">u(b)=\\e^b-2b</span>（<span class=\"gk-math\" data-tex=\"b&gt;1\">b&gt;1</span>），则 <span class=\"gk-math\" data-tex=\"u^{\\prime}(b)=\\e^b-2&gt;\\e-2&gt;0\">u^{\\prime}(b)=\\e^b-2&gt;\\e-2&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"u\">u</span> 在 <span class=\"gk-math\" data-tex=\"(1,+\\infty)\">(1,+\\infty)</span> 上为增函数，所以 <span class=\"gk-math\" data-tex=\"u(b)&gt;u(1)=\\e-2&gt;0\">u(b)&gt;u(1)=\\e-2&gt;0</span>. 故 <span class=\"gk-math\" data-tex=\"S(b)&gt;0\">S(b)&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"S(x)=0\">S(x)=0</span> 有两个不同零点，即 <span class=\"gk-math\" data-tex=\"\\e^x-x=b\">\\e^x-x=b</span> 有两个不同解. 设 <span class=\"gk-math\" data-tex=\"T(x)=x-\\ln x-b\">T(x)=x-\\ln x-b</span>（<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>），则 <span class=\"gk-math\" data-tex=\"T^{\\prime}(x)=\\frac{x-1}{x}\">T^{\\prime}(x)=\\frac{x-1}{x}</span>. 当 <span class=\"gk-math\" data-tex=\"0&lt;x&lt;1\">0&lt;x&lt;1</span> 时 <span class=\"gk-math\" data-tex=\"T^{\\prime}(x)&lt;0\">T^{\\prime}(x)&lt;0</span>，当 <span class=\"gk-math\" data-tex=\"x&gt;1\">x&gt;1</span> 时 <span class=\"gk-math\" data-tex=\"T^{\\prime}(x)&gt;0\">T^{\\prime}(x)&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"T\">T</span> 在 <span class=\"gk-math\" data-tex=\"(0,1)\">(0,1)</span> 上为减函数，在 <span class=\"gk-math\" data-tex=\"(1,+\\infty)\">(1,+\\infty)</span> 上为增函数，所以 <span class=\"gk-math\" data-tex=\"T(x)_{\\min}=T(1)=1-b&lt;0\">T(x)_{\\min}=T(1)=1-b&lt;0</span>. 而 <span class=\"gk-math\" data-tex=\"T(\\e^{-b})=\\e^{-b}&gt;0\">T(\\e^{-b})=\\e^{-b}&gt;0</span>，<span class=\"gk-math\" data-tex=\"T(\\e^b)=\\e^b-2b&gt;0\">T(\\e^b)=\\e^b-2b&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"T(x)=0\">T(x)=0</span> 有两个不同零点，即 <span class=\"gk-math\" data-tex=\"x-\\ln x=b\">x-\\ln x=b</span> 有两个不同解. 当 <span class=\"gk-math\" data-tex=\"b=1\">b=1</span> 时，由（1）的单调性，所以两方程各仅有一个解，当 <span class=\"gk-math\" data-tex=\"b&lt;1\">b&lt;1</span> 时均无解. 故若直线 <span class=\"gk-math\" data-tex=\"y=b\">y=b</span> 与两曲线共有三个不同交点，则 <span class=\"gk-math\" data-tex=\"b&gt;1\">b&gt;1</span>. 设 <span class=\"gk-math\" data-tex=\"h(x)=\\e^x+\\ln x-2x\">h(x)=\\e^x+\\ln x-2x</span>（<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>），则 <span class=\"gk-math\" data-tex=\"h^{\\prime}(x)=\\e^x+\\frac1x-2\">h^{\\prime}(x)=\\e^x+\\frac1x-2</span>. 设 <span class=\"gk-math\" data-tex=\"s(x)=\\e^x-x-1\">s(x)=\\e^x-x-1</span>（<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>），则 <span class=\"gk-math\" data-tex=\"s^{\\prime}(x)=\\e^x-1&gt;0\">s^{\\prime}(x)=\\e^x-1&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"s\">s</span> 在 <span class=\"gk-math\" data-tex=\"(0,+\\infty)\">(0,+\\infty)</span> 上为增函数，所以 <span class=\"gk-math\" data-tex=\"s(x)&gt;s(0)=0\">s(x)&gt;s(0)=0</span>，即 <span class=\"gk-math\" data-tex=\"\\e^x&gt;x+1\">\\e^x&gt;x+1</span>. 所以 <span class=\"gk-math\" data-tex=\"h^{\\prime}(x)&gt;x+\\frac1x-1\\ge 2-1&gt;0\">h^{\\prime}(x)&gt;x+\\frac1x-1\\ge 2-1&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"h\">h</span> 在 <span class=\"gk-math\" data-tex=\"(0,+\\infty)\">(0,+\\infty)</span> 上为增函数. 而 <span class=\"gk-math\" data-tex=\"h(1)=\\e-2&gt;0\">h(1)=\\e-2&gt;0</span>，并且 <span class=\"gk-math\" data-tex=\"h\\left(\\frac1{\\e^3}\\right)=\\e^{\\frac1{\\e^3}}-3-\\frac2{\\e^3}&lt;\\e-3-\\frac2{\\e^3}&lt;0\">h\\left(\\frac1{\\e^3}\\right)=\\e^{\\frac1{\\e^3}}-3-\\frac2{\\e^3}&lt;\\e-3-\\frac2{\\e^3}&lt;0</span>，故 <span class=\"gk-math\" data-tex=\"h\">h</span> 在 <span class=\"gk-math\" data-tex=\"(0,+\\infty)\">(0,+\\infty)</span> 上有且只有一个零点 <span class=\"gk-math\" data-tex=\"x_0\">x_0</span>，且 <span class=\"gk-math\" data-tex=\"\\frac1{\\e^3}&lt;x_0&lt;1\">\\frac1{\\e^3}&lt;x_0&lt;1</span>. 当 <span class=\"gk-math\" data-tex=\"0&lt;x&lt;x_0\">0&lt;x&lt;x_0</span> 时 <span class=\"gk-math\" data-tex=\"h(x)&lt;0\">h(x)&lt;0</span>，即 <span class=\"gk-math\" data-tex=\"\\e^x-x&lt;x-\\ln x\">\\e^x-x&lt;x-\\ln x</span>，即 <span class=\"gk-math\" data-tex=\"f(x)&lt;g(x)\">f(x)&lt;g(x)</span>. 当 <span class=\"gk-math\" data-tex=\"x&gt;x_0\">x&gt;x_0</span> 时 <span class=\"gk-math\" data-tex=\"h(x)&gt;0\">h(x)&gt;0</span>，即 <span class=\"gk-math\" data-tex=\"f(x)&gt;g(x)\">f(x)&gt;g(x)</span>. 因此若直线 <span class=\"gk-math\" data-tex=\"y=b\">y=b</span> 与两曲线共有三个不同交点，则 <span class=\"gk-math\" data-tex=\"b=f(x_0)=g(x_0)&gt;1\">b=f(x_0)=g(x_0)&gt;1</span>. 此时 <span class=\"gk-math\" data-tex=\"\\e^x-x=b\">\\e^x-x=b</span> 有两个不同根 <span class=\"gk-math\" data-tex=\"x_1\">x_1</span>，<span class=\"gk-math\" data-tex=\"x_0\">x_0</span>（<span class=\"gk-math\" data-tex=\"x_1&lt;0&lt;x_0\">x_1&lt;0&lt;x_0</span>），<span class=\"gk-math\" data-tex=\"x-\\ln x=b\">x-\\ln x=b</span> 有两个不同根 <span class=\"gk-math\" data-tex=\"x_0\">x_0</span>，<span class=\"gk-math\" data-tex=\"x_4\">x_4</span>（<span class=\"gk-math\" data-tex=\"0&lt;x_0&lt;1&lt;x_4\">0&lt;x_0&lt;1&lt;x_4</span>）. 故 <span class=\"gk-math\" data-tex=\"\\e^{x_1}-x_1=b\">\\e^{x_1}-x_1=b</span>，<span class=\"gk-math\" data-tex=\"\\e^{x_0}-x_0=b\">\\e^{x_0}-x_0=b</span>，<span class=\"gk-math\" data-tex=\"x_4-\\ln x_4-b=0\">x_4-\\ln x_4-b=0</span>，<span class=\"gk-math\" data-tex=\"x_0-\\ln x_0-b=0\">x_0-\\ln x_0-b=0</span>. 所以 <span class=\"gk-math\" data-tex=\"x_4-b=\\ln x_4\">x_4-b=\\ln x_4</span>，即 <span class=\"gk-math\" data-tex=\"\\e^{x_4-b}=x_4\">\\e^{x_4-b}=x_4</span>，从而 <span class=\"gk-math\" data-tex=\"\\e^{x_4-b}-\\left(x_4-b\\right)-b=0\">\\e^{x_4-b}-\\left(x_4-b\\right)-b=0</span>，故 <span class=\"gk-math\" data-tex=\"x_4-b\">x_4-b</span> 为方程 <span class=\"gk-math\" data-tex=\"\\e^x-x=b\">\\e^x-x=b</span> 的解. 又由 <span class=\"gk-math\" data-tex=\"x_0-\\ln x_0-b=0\">x_0-\\ln x_0-b=0</span> 得 <span class=\"gk-math\" data-tex=\"\\ln x_0=x_0-b\">\\ln x_0=x_0-b</span>，即 <span class=\"gk-math\" data-tex=\"\\e^{x_0-b}=x_0\">\\e^{x_0-b}=x_0</span>，从而 <span class=\"gk-math\" data-tex=\"\\e^{x_0-b}-\\left(x_0-b\\right)-b=0\">\\e^{x_0-b}-\\left(x_0-b\\right)-b=0</span>，故 <span class=\"gk-math\" data-tex=\"x_0-b\">x_0-b</span> 也为方程 <span class=\"gk-math\" data-tex=\"\\e^x-x=b\">\\e^x-x=b</span> 的解. 又 <span class=\"gk-math\" data-tex=\"\\e^{x_1}-x_1=b\">\\e^{x_1}-x_1=b</span> 可化为 <span class=\"gk-math\" data-tex=\"\\e^{x_1}=x_1+b\">\\e^{x_1}=x_1+b</span>，即 <span class=\"gk-math\" data-tex=\"x_1-\\ln\\left(x_1+b\\right)=0\">x_1-\\ln\\left(x_1+b\\right)=0</span>，即 <span class=\"gk-math\" data-tex=\"\\left(x_1+b\\right)-\\ln\\left(x_1+b\\right)-b=0\">\\left(x_1+b\\right)-\\ln\\left(x_1+b\\right)-b=0</span>，故 <span class=\"gk-math\" data-tex=\"x_1+b\">x_1+b</span> 为方程 <span class=\"gk-math\" data-tex=\"x-\\ln x=b\">x-\\ln x=b</span> 的解. 又 <span class=\"gk-math\" data-tex=\"\\e^{x_0}-x_0=b\">\\e^{x_0}-x_0=b</span> 可化为 <span class=\"gk-math\" data-tex=\"\\e^{x_0}=x_0+b\">\\e^{x_0}=x_0+b</span>，即 <span class=\"gk-math\" data-tex=\"x_0-\\ln\\left(x_0+b\\right)=0\">x_0-\\ln\\left(x_0+b\\right)=0</span>，即 <span class=\"gk-math\" data-tex=\"\\left(x_0+b\\right)-\\ln\\left(x_0+b\\right)-b=0\">\\left(x_0+b\\right)-\\ln\\left(x_0+b\\right)-b=0</span>，故 <span class=\"gk-math\" data-tex=\"x_0+b\">x_0+b</span> 也为方程 <span class=\"gk-math\" data-tex=\"x-\\ln x=b\">x-\\ln x=b</span> 的解. 所以 <span class=\"gk-math\" data-tex=\"\\{x_1,x_0\\}=\\{x_0-b,x_4-b\\}\">\\{x_1,x_0\\}=\\{x_0-b,x_4-b\\}</span>，而 <span class=\"gk-math\" data-tex=\"b&gt;1\">b&gt;1</span>，<span class=\"gk-math\" data-tex=\"x_0\\in(0,1)\">x_0\\in(0,1)</span>，故 <span class=\"gk-math\" data-tex=\"x_0-b&lt;0&lt;x_0\">x_0-b&lt;0&lt;x_0</span>，因此 <span class=\"gk-math\" data-tex=\"x_0-b\">x_0-b</span> 必为负根 <span class=\"gk-math\" data-tex=\"x_1\">x_1</span>，<span class=\"gk-math\" data-tex=\"x_4-b\">x_4-b</span> 必为正根 <span class=\"gk-math\" data-tex=\"x_0\">x_0</span>，即 <span class=\"gk-math\" data-tex=\"x_1=x_0-b\">x_1=x_0-b</span>，<span class=\"gk-math\" data-tex=\"x_0=x_4-b\">x_0=x_4-b</span>，于是 <span class=\"gk-math\" data-tex=\"x_1+x_4=2x_0\">x_1+x_4=2x_0</span>. 所以直线 <span class=\"gk-math\" data-tex=\"y=b\">y=b</span> 与两条曲线从左到右的三个交点的横坐标成等差数列. 证毕.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]}];
